  str_mission_desc_4001010 = "Pela primeira vez em 17 anos, você usou sua habilidade psíquica. Seria a jovem, à sua frente, sua chance de ir embora?",
  str_mission_desc_4001020 = "Você nunca conheceu seu povo, mas agora possui uma amiga.",
  str_mission_desc_4001030 = "Talvez a Colossus esteja pronta pra ser ativada?",
  str_mission_desc_4001040 = "Enquanto houver luz, os Aurorians não vão parar de lutar.",
  str_mission_desc_4001041 = "Existem cada vez mais Eclipsitas. Melhor tentar outras soluções se estiver difícil.",
