  str_mission_desc_4001043 = "Teste",
  str_mission_desc_4001044 = "Teste",
  str_mission_desc_4001045 = "Teste",
  str_mission_desc_4001046 = "Teste",
  str_mission_desc_4001047 = "Teste",
  str_mission_desc_4001050 = "Guiado pela Srta. Blanc, você tem uma ideia melhor de como chegar ao seu destino.",
  str_mission_desc_4001051 = "Você nunca lutou em uma batalha como agora. Os Aurorians e você são uma boa combinação.",
