  str_mission_desc_4001070 = "No momento crítico, o chão começou a tremer e algo se aproximava...",
  str_mission_desc_4001080 = "Soroz não conseguia levantar voo, por enquanto. Antes disso, você precisou enfrentar inúmeros Eclipsitas.",
  str_mission_desc_4001090 = "Os Eclipsitas foram encontrados em todas as áreas da Colossus. Defenda até o fim!",
  str_mission_desc_4001100 = "Um número crescente de Eclipsitas invadiu a seção vital da Colossus – a Ponte.",
  str_mission_desc_4001101 = "Crises desconhecidas espreitavam.",
  str_mission_desc_4001110 = "Se você não tem vantagem numérica, repense suas táticas.",
  str_mission_desc_4001120 = "Você deve ir com todos os seus companheiros!",
  str_mission_desc_4001130 = "Acompanhada do rugido do motor, a Colossus levantou voo. No entanto, um rival mais forte que Kraken surgia das sombras.",
  str_mission_desc_4002015 = "Um sacrifício aliado e notícias inesperadas... Tudo parecia mergulhar em escuridão. Aonde tudo isso vai levar?",
  str_mission_desc_4002010 = "Soroz caiu em terras selvagens devido a falhas.",
  str_mission_desc_4002035 = "Teste",
  str_mission_desc_4002020 = "Você vai comandar um grupo de desastrados dessa vez...",
  str_mission_desc_4002030 = "A Rediesel Wrench era mais forte que tudo. No entanto, os Eclipsitas lhe colocaram em um impasse.",
