  str_mission_desc_4002040 = "Considerando as possibilidades de combate e as feridas de Vice, os caras da Rediesel Wrench encurralaram você.",
  str_mission_desc_4002050 = "A situação não parece boa. Os Eclipsitas parecem avançar até a Colossus...",
  str_mission_desc_4002060 = "Enquanto todos supunham que um Eclipsita de alto nível estava no comando, um novo Eclipsita, Umbrahulk, apareceu.",
  str_mission_desc_4002070 = "Comandado por Nozard, os Eclipsitas ameaçavam os cidadãos da subcidade. Para conservar força, você não teve escolha a não ser recuar!",
  str_mission_desc_4002080 = "Você foi pego de surpresa pelos Eclipsitas. Felizmente, não era tarde demais...",
  str_mission_desc_4002090 = "A subcidade foi capturada pelos Eclipsitas. Era esse o fim?",
  str_mission_desc_4002100 = "A subcidade 28 caiu, e na mão de Charon estava o meio final para eliminar totalmente os inimigos.",
  str_mission_desc_4002101 = "Deixe os feridos e os cidadãos embarcarem na Colossus! Não abaixem a guarda!",
  str_mission_desc_4002110 = "O peso da responsabilidade começou a cair nos seus ombros. Amigos, superiores, cidadãos... Que caminho seguir...?",
  str_mission_desc_4002120 = "Quando cercado, Charon gritou, apressando você \na fugir. Ele cairia com a subcidade 28...",
  str_mission_desc_4003010 = "Com a ajuda de Vice e Soroz, a busca pelo seu povo parecia ir bem.",
  str_mission_desc_4003020 = "Um dos seus pedia por ajuda. Ele parecia  estar correndo perigo?!",
  str_mission_desc_4003030 = "Parece que chegaram antes de você. Há sinais de Eclipsitas por todo lugar.",
  str_mission_desc_4003031 = "O sinal não é bom. “Aquela pessoa” está sendo perseguida. Apresse-se.",
  str_mission_desc_4003040 = "O caminho para as relíquias era duro e íngreme, infestado de Eclipsitas.",
  str_mission_desc_4003050 = "Um bando de Eclipsitas apareceu. Quem estava por trás disso?",
  str_mission_desc_4003060 = "Você o encontrou! Mas ele estava sendo perseguido\npor inimigos que viraram traidores...",
  str_mission_desc_4003070 = "Ninguém era capaz de dizer a força de seus inimigos. Ainda assim... Não havia volta.",
  str_mission_desc_4003080 = "Schummer pôs suas mãos no Módulo de Tanque Pensante. Era tarde demais... Mas você não escapará!",
  str_mission_desc_4003090 = "Mendelson ficava cada vez mais fraco, mas você continuava em frente sem hesitar.",
  str_mission_desc_4003091 = "Você se aproximava de seu destino. Farejou seus inimigos?",
  str_mission_desc_4003100 = "O ar era cheio de incertezas, coberto por uma névoa pesada que se estendia para a escuridão.",
  str_mission_desc_4003110 = "A energia sombria estava dominando cada centímetro de Mendelson. Seu corpo feito uma vela ao vento!",
  str_mission_desc_4003120 = "Cercado por escuridão e ansiedade, você ouviu um pequeno sinal de comunicação entre os Eclipsitas de alto nível. O julgamento supremo se aproximava.",
  str_mission_desc_4004010 = "A área leste da Baixa Lumópolis foi invadida por Eclipsitas. Rapidez é essencial e a vitória é necessária.",
  str_mission_desc_4004020 = "Os Eclipsitas foram vistos na área oeste! Os fugitivos estavam aterrorizando em todo o lugar.",
  str_mission_desc_4004030 = "O número de Eclipsitas é maior do que você imaginou. Evacuação e abrigo pros cidadãos eram prioridade.",
  str_mission_desc_4004031 = "Guardiões estavam derrotando os Eclipsitas restantes um a um. Nenhum deles conseguia escapar à caçada.",
  str_mission_desc_4004040 = "Num canto remoto da área oeste, os Eclipsitas invocados esperavam há muito tempo.",
  str_mission_desc_4004050 = "Os Eclipsitas atacaram de novo e de novo, mas podia ser apenas uma distração...",
  str_mission_desc_4004060 = "Shelt decidiu fazer tudo que podia por seus objetivos: ela despertou sua irmã, que também tornou-se uma Eclipsita...",
  str_mission_desc_4004070 = "Concentre-se em localizar as irmãs Eclipsitas e eliminar as pragas.",
  str_mission_desc_4004080 = "As irmãs Eclipsitas fizeram de caso pensado, invocando hordas infinitas de Eclipsitas.",
  str_mission_desc_4004090 = "Estava se aproximando. Você quase capturou o líder que planejou essas interferências.",
  str_mission_desc_4004091 = "Mate todos. Nenhum será poupado.",
  str_mission_desc_4004100 = "Aonde estava o suspeito? Quem diabos era ele?",
  str_mission_desc_4004110 = "O sangue das irmãs Eclipsitas manchou a cidade. Não havia como voltar atrás.",
  str_mission_desc_4004120 = "Era hora de julgar as irmãs. Como os inimigos desesperados resistiriam...",
  str_mission_desc_4005010 = "O número de Colossi caídas indicava o número de Celestitas sacrificados, bem como o número de Eclipsitas com sangue nas mãos...",
  str_mission_desc_4005020 = "O interior das Colossus caídas estava severamente danificado, por isso o caminho até a Unidade de Crescimento Autônomo era perigosa.",
  str_mission_desc_4005030 = "O perigo espreitava entre as relíquias, pois os Eclipsitas surgiam repentinamente das sombras.",
  str_mission_desc_4005031 = "Atingir o calcanhar de Aquiles era a chave pra escapar do perigo.",
  str_mission_desc_4005040 = "Esteja alerta. Você pode se machucar por conta dos Eclipsitas e de armadilhas despercebidas.",
  str_mission_desc_4005050 = "Uma boa isca escapa impune com seus movimentos.",
  str_mission_desc_4005060 = "Uma melodia piedosa foi tocada gentilmente. A Colossus começou a brilhar novamente. Esse foi o último presente, meu povo.",
  str_mission_desc_4005070 = "A surpresa na Colossus mexeu com seus pensamentos. Soluções precisavam ser pensadas cuidadosamente.",
  str_mission_desc_4005080 = "Soldados em perseguição não paravam de surgir, como moscas irritantes.",
  str_mission_desc_4005090 = "Apenas 5 minutos restantes até o prazo limite. Qual é sua decisão?",
  str_mission_desc_4005091 = "Uma fuga cuidadosa e estratégias ousadas foram essenciais.",
  str_mission_desc_4005100 = "Seja proativo, não fique moscando.",
  str_mission_desc_4005110 = "Tem sempre uma saída, e você veria isso caso se adaptasse.",
  str_mission_desc_4005120 = "A contagem regressiva estava terminando. Um ataque surpresa viraria o jogo? Era a hora do golpe final em Schummer!",
  str_mission_desc_4006010 = "Quando estava atrás Do Módulo de Controle de Chamas, no Corredor Suspirante, você achou botas militares. Devem pertencer ao traidor, Gertzurde.",
  str_mission_desc_4006020 = "Para ficar à frente de Schummer, você se apressou.",
  str_mission_desc_4006030 = "Carleen e Vice buscavam o Módulo de Controle de Chamas desesperadamente, enquanto sofriam seguidas emboscadas inimigas...",
  str_mission_desc_4006031 = "Escuridão, frio, e quietude... Lutar sozinho era insuportável, mas você estava mesmo sem suporte?",
  str_mission_desc_4006040 = "Até mesmo com o suporte remoto de Sra. Sheol, as confusas curvas do Corredor Suspirante deixaram você confuso.",
  str_mission_desc_4006050 = "Gertzurde parecia espreitar logo adiante. Seria essa a batalha final?",
  str_mission_desc_4006060 = "“Você... matou Shelt!” O vingador apareceu à sua frente...",
  str_mission_desc_4006070 = "O Módulo de Controle de Chamas estava ao alcance. O que o inimigo tramava?",
  str_mission_desc_4006080 = "O número de Eclipsitas estava aumentando, e as batalhas constantes deixaram todos exaustos...",
  str_mission_desc_4006090 = "Nunca descanse... Os passos de Gertzurde se aproximavam e você podia sentir o aroma de vingança.",
  str_mission_desc_4006091 = "Qualquer impasse encarado, seus companheiros viriam até você independentemente do perigo...",
  str_mission_desc_4006100 = "Você não foi parado pelas armadilhas e emboscadas pelo caminho. Gertzurde precisava fazer uma pergunta para Schummer...",
  str_mission_desc_4006110 = "Enfim, você alcançou as profundezas do Corredor Suspirante e, se nada de “inesperado” acontecer, o Módulo de Controle de Chamas deve estar aqui...",
  str_mission_desc_4006120 = "Gertzurde conseguiria o que buscava? Schummer conseguiria realizar sua promessa em batalha? Sua jornada estava quase no fim.",
  str_mission_desc_4007010 = "Você decidiu se separar para garantir que as operações de apoio e resgate fossem realizadas ao mesmo tempo.",
  str_mission_desc_4007020 = "Baixa Lumópolis estava infestada de Eclipsitas, mas suas operações pareciam seguir bem?",
  str_mission_desc_4007030 = "Você ficou desolado por não sentir a presença de Soroz, mas era necessário proteger os cidadãos de Baixa Lumópolis, mesmo sem habilidades de combate...",
  str_mission_desc_4007031 = "Nesse momento, algo crescia em Lumópolis...",
  str_mission_desc_4007040 = "As garras da ameaça em seu pescoço, e intensas batalhas nas ruas, era um desafio\nque você nunca havia encarado.",
  str_mission_desc_4007050 = "Operações de suporte na Baixa Lumópolis terminaram, mas a Cidade Alta estava sob ataque?!",
  str_mission_desc_4007060 = "Indo para a Cidade Alta, um familiar, porém estranho, inimigo apareceu, gigante e assustador...",
  str_mission_desc_4007070 = "Era uma batalha em defesa de tudo que desejavam proteger...---",
  str_mission_desc_4007080 = "A batalha era de vida ou morte, e você tinha de correr contra o tempo para ganhar.",
  str_mission_desc_4007090 = "O pânico foi aumentando sem parar. Você não pode deixar Eclipsitas destruírem Soroz de novo!",
  str_mission_desc_4007100 = "Uma mensagem de Soroz. Seria isso...?!",
  str_mission_desc_4007110 = "A temperatura começou a cair rapidamente e você pode sentir o cheiro de Schummer, ali!",
  str_mission_desc_4007111 = "O componente de “consciência” de Soroz realmente se foi? Seu laço com ele sumiria também?",
  str_mission_desc_4007120 = "Schummer se tornou uma pessoa completamente diferente depois de possuir todos os módulos.\nIsso era uma batalha ou um jogo... solitário?",
  str_mission_desc_4008020 = "Schummer mantinha você preso a Aviduz, então Vice veio salvá-lo. Você decidiu encontrar Líder Vivian e levá-la com você...",
  str_mission_desc_4008030 = "Quanto mais você andava, mais seu corpo parecia estranho, mas não havia tempo de se preocupar com isso. Precisava encontrar Vivian o mais rápido possível.",
  str_mission_desc_4008040 = "Você avançou discretamente e rapidamente lidou com inimigos no caminho.",
  str_mission_desc_4008041 = "Ludibriados, enganados, traídos... Os Eclipsitas serão pegos de surpresa.",
  str_mission_desc_4008050 = "O interior da Colossus Negro era bastante complexo, exigindo muito cuidado...",
  str_mission_desc_4008060 = "Schummer não te achou ainda. Continue... talvez a Chefe Vivian esteja na próxima sala!",
  str_mission_desc_4008070 = "Quando Curie abriu caminho, você finalmente alcançou o lugar onde Líder Vivian estava presa, e um inimigo poderoso lhe aguardava...",
  str_mission_desc_4008090 = "Líder Vivian foi resgatada com sucesso, então era urgente deixar pra trás aquele lugar sinistro. Mas essa era mesmo a escolha mais racional?",
  str_mission_desc_4008100 = "Um barulho alto soou. A  situação mudou. Carleen venceu, ou Schummer enfim triunfou!?",
  str_mission_desc_4008110 = "Sua estratégia mudou de fuga para ataque! Era sua última chance de atrapalhar a formação inimiga!",
  str_mission_desc_4008111 = "Que desafios você pode esperar da nefasta Aviduz?",
  str_mission_desc_4008120 = "O caminho que leva até a ponte é repleto de perigos, e os Eclipsitas entraram em frenesi...",
  str_mission_desc_4008130 = "Siga em frente... Schummer deve estar perto!",
  str_mission_desc_4008140 = "Finalmente, o momento decisivo chegou. Lumópolis e a Colossus Negro... Hoje, um cairá e você será testemunha...",
  str_mission_desc_4009020 = "Você seguiu a trilha de destroços da Aviduz e voltou a Eraveil, onde tudo começou.",
  str_mission_desc_4009030 = "Será que tem mais alguém aqui além dos Eclipsitas?",
  str_mission_desc_4009040 = "Há ainda mais perigo à frente, assim como um certo rosto familiar...",
  str_mission_desc_4009041 = "Encontre os pontos fracos e use um inimigo para derrotar outro.",
  str_mission_desc_4009050 = "Com Sinsa no grupo, explorar Eraveil ficou muito mais fácil.",
  str_mission_desc_4009060 = "O Fluxo Escuro pode ter esfriado o clima, mas você deve seguir em frente.",
  str_mission_desc_4009070 = "As emoções estão à flor da pele. De onde veio esse choro? Foi um Eclipsita?",
  str_mission_desc_4009090 = "O chão tremeu e uma aura assustadora surgiu...",
  str_mission_desc_4009100 = "Use suas habilidades psíquicas para avançar e encontre uma maneira de romper a formação do inimigo!",
  str_mission_desc_4009110 = "É como se os inimigos surgissem do nada e até parecem estar em sincronia.",
  str_mission_desc_4009111 = "Se não consegue derrotar o inimigo de frente, tente criar uma oportunidade de outra forma.",
  str_mission_desc_4009120 = "Um inimigo difícil apareceu... É hora de livrar Eraveil da sua presença maligna!",
  str_mission_desc_4009130 = "Um inimigo ainda mais forte te espera. Antes de entrar na batalha, você deve escapar do cerco Eclipsita...",
  str_mission_desc_4009140 = "Os destroços da Aviduz estão bem à frente! Mas quem é aquele parado na frente dela!?",
  str_mission_desc_4010020 = "A Aviduz estava bem na sua frente. Perseguir Forsakin, confirmar se Schummer ainda está viva... O que quer que tenha acontecido a seguir, sua única opção era entrar...",
  str_mission_desc_4010030 = "Com suas habilidades psíquicas, você concluiu que Schummer está... comendo Eclipsitas!?",
  str_mission_desc_4010040 = "Nem todos os Eclipsitas estavam tentando se salvar, alguns estavam preparados para lutar com você até a morte.",
  str_mission_desc_4010041 = "Se as chances estão contra você, tente usar o ambiente para ganhar vantagem!",
  str_mission_desc_4010050 = "Incontáveis Eclipsitas vagavam pela Aviduz, como vermes dentro de um cadáver em decomposição.",
  str_mission_desc_4010060 = "Os Eclipsitas pareciam determinados a bloquear seu caminho.",
  str_mission_desc_4010070 = "Outro inimigo familiar apareceu. Parece que a magia da ressurreição de Forsakin não pode ser subestimada...",
  str_mission_desc_4010090 = "Ao confirmar seu sonho sobre Eraveil, sua raiva foi reacendida.",
  str_mission_desc_4010100 = "O inimigo diante de você parece ter a habilidade de selar Luminática! Esta será uma batalha difícil.",
  str_mission_desc_4010110 = "Os Eclipsitas bloqueando o caminho não tinham intenção de desistir tão facilmente.",
  str_mission_desc_4010111 = "O fluxo constante de Eclipsitas parecia não ter fim...",
  str_mission_desc_4010120 = "Os Eclipsitas estavam tentando forçar uma situação desesperadora!",
  str_mission_desc_4010130 = "Schummer estava logo à frente. Você não precisou usar suas habilidades psíquicas para saber... O chão tremendo e o Fluxo Escuro desenfreado são suficientes pra saber.",
  str_mission_desc_4010140 = "Derrote Schummer!",
  str_mission_desc_4101020 = "Oprimido pelo Darkflow, você enfrenta mais dificuldades na batalha. Mas você não pode recuar para a segurança de Soroz!",
  str_mission_desc_4101030 = "Nas profundezas da Cidade Baixa, vestígios de guerra estão enterrados junto com outros segredos...",
  str_mission_desc_4101040 = "Como os Eclipsitos de Alto Nível chegaram aqui? Correr! Não pare!",
  str_mission_desc_4101060 = "Reinhardt tem observado você. Para garantir sua segurança, ela foi consumida pela ansiedade e preocupações.",
  str_mission_desc_4101070 = "O que diabos aconteceu em Undercity 80? Talvez Reinhardt tenha uma resposta.",
  str_mission_desc_4101080 = "Em breve você vai pousar. Haveria esperança de um retorno seguro esperando?",
  str_mission_desc_4101090 = "O ódio duradouro não pode ser facilmente acalmado. Às vezes, sair pode ser a melhor escolha.",
  str_mission_desc_4201020 = "Soroz está sendo emboscado por Eclipsites? Não entremos em pânico. Vamos tirá-los do Colosso!",
  str_mission_desc_4201030 = "O fato de Eclipsites ter conseguido atacar Soroz indica que alguém está por trás de tudo isso. Esta não foi uma simples emboscada!",
  str_mission_desc_4201040 = "De qualquer forma, não é um acidente se cair onde deveria.",
  str_mission_desc_4201041 = "Encontrar Eclipsites enquanto procurava a entrada não fazia parte do plano, mas não há tempo a perder, vamos tirá-los rapidamente.",
  str_mission_desc_4201050 = "Ainda bem que você tem um detector de metais para ajudar a iniciar nossa busca pela entrada. Mas, pode realmente encontrar algo útil?",
  str_mission_desc_4201060 = "Este lugar está vazio... Tudo o que resta são ecos e fragmentos do passado.",
  str_mission_desc_4201061 = "Continue explorando e procurando... Vamos fazer o nosso melhor para encontrar a luz da esperança nas profundezas.",
  str_mission_desc_4201070 = "Uma presença desconhecida observa a batalha e está seguindo cada movimento seu.",
  str_mission_desc_4201080 = "Não pare e não olhe para trás. Continue correndo e buscando aquele lado bom.",
  str_mission_desc_4201090 = "Que atos perversos alguém deve cometer para ser exilado em tal abismo?",
  str_mission_desc_4201100 = "Não é aqui, mas mais profundo. Continue seguindo em frente, mas fique atento às ameaças do passado.",
  str_mission_desc_4201120 = "Caelestites, Aurorianos, Eclipsitas, Colossos... Imagino quantos segredos estão escondidos nesta vasta e há muito abandonada base...",
  str_mission_desc_4201130 = "Não são apenas os muros e portões da base que guardam esses segredos, mas também esses Eclipsites aqui.",
  str_mission_desc_4201140 = "O Neural Aux está danificado e não há como inserir comandos corretamente. Que tal... reiniciá-lo primeiro?",
  str_mission_desc_4202020 = "Parece haver eclipses nesta torre. Eles já estavam aqui para começar?",
  str_mission_desc_4202030 = "Conforme você continua seguindo em frente, você encontra algo desconhecido e inesperado.",
  str_mission_desc_4202040 = "Você tem ouvido barulhos estranhos atrás de você há algum tempo. Os Eclipsites estão no seu encalço... ou algo mais?",
  str_mission_desc_4202041 = "Desde quando Eclipsites ficou esperto o suficiente para usar armadilhas?! Mantenha os olhos abertos e vamos derrotá-los!",
  str_mission_desc_4202050 = "O que há com todas essas armadilhas que levam à Chord Zone?! Gostaria de saber se eles poderiam ser usados...",
  str_mission_desc_4202060 = "Barton decidiu usar o Chord Link para escapar dessa situação difícil. Faça o que puder para lhe dar algum tempo!",
  str_mission_desc_4202070 = "Calma aí... Só mais um pouco e as coisas vão virar a seu favor.",
  str_mission_desc_4202090 = "A batalha está acontecendo fora da torre, e os reforços finalmente chegaram. Agora só resta lutar.",
  str_mission_desc_4202100 = "Todo mundo está dando tudo de si no campo de batalha, mas quanto tempo eles podem aguentar?",
  str_mission_desc_4202115 = "Os aurorianos do lado de fora da Torre do Retorno estão fazendo o possível para encontrar uma chance de virar a maré.",
  str_mission_desc_4202111 = "Parece que um encrenqueiro entrou no campo de batalha. O tempo está acabando. Vamos atacar, agora!",
  str_mission_desc_4202120 = "Ainda há Eclipsites bloqueando o caminho para o Anel Central e desafios ainda mais difíceis pela frente.",
  str_mission_desc_4202130 = "Há algumas coisas que só você pode fazer. Todo mundo está aqui, pronto para ajudar, então vá em frente.",
  str_mission_desc_4202140 = "É um chamado para retornar, não apenas para você, mas para a esperança.",
  str_mission_desc_4203020 = "Para entender melhor a condição de Vice, você concorda em permitir que a Illumina pesquise novos módulos de dados encontrados em Soroz.",
  str_mission_desc_4203030 = "Depois de entrar no campo de batalha simulado, você começa a realizar testes de acordo com as instruções dos pesquisadores. No mínimo, as batalhas são bastante fáceis... por enquanto.",
  str_mission_desc_4203040 = "Você usa o simulador de batalha mais uma vez, mas desta vez o terreno e o ambiente mudaram.",
  str_mission_desc_4203041 = "Há caos e perigo por toda parte, e você está completamente perdido... Você não pode ficar aqui por muito mais tempo!",
  str_mission_desc_4203050 = "Espere. Ninguém disse que a simulação seria tão difícil!",
  str_mission_desc_4203060 = "O que é este lugar? Por que não o vi antes? Vício? Reinhardt? Vocês podem me ouvir?",
  str_mission_desc_4203070 = "Soldados desesperados sendo esmagados por um ataque selvagem de Eclipsite... Isso é o fim do mundo?",
  str_mission_desc_4203090 = "O Guardião Um, responsável por todas as operações diárias da Federação Illumina... parece menor do que o esperado.",
  str_mission_desc_4203100 = "Apesar de ser a primeira vez que você encontra o Guardião Um, um sentimento de confiança puro e natural é estabelecido entre vocês dois.",
  str_mission_desc_4203110 = "É impossível ficar com os dois pés no chão em um ambiente virtual. Mesmo assim, sua única escolha é seguir em frente.",
  str_mission_desc_4203111 = "Este experimento busca testar os limites da própria força para descobrir a menor chance de quebrá-los.",
  str_mission_desc_4203120 = "Estenda a mão, corra mais rápido - você está a apenas um passo de alcançá-la.",
  str_mission_desc_4203130 = "É hora de consertar as coisas. Afinal, é por isso que você veio aqui em primeiro lugar.",
  str_mission_desc_4203140 = "Depois de um tempo indeterminado, você finalmente chega à falha final.",
  str_mission_desc_4204020 = "A poderosa e importante arma conhecida como \"Combat Cyborg\" é na verdade...",
  str_mission_desc_4204030 = "Sean retorna da zona de guerra o mais rápido que pode. Ele recebeu a notícia da guarnição Illumina de que você estava a caminho.",
  str_mission_desc_4204031 = "Às vezes, atacar direto para o combate não é a melhor opção.",
  str_mission_desc_4204040 = "Você continua sua jornada para Crepúsculo, onde três velhos amigos finalmente se reencontram.",
  str_mission_desc_4204050 = "Depois de finalmente alcançar os arredores de Crepúsculo, a sobrecarga da aurora começa a ficar fora de controle, significando um desastre para aqueles que vivem abaixo.",
  str_mission_desc_4204060 = "Ainda há civis atrás de você tentando escapar! Não deixe nem mesmo um único Eclipsite passar por você!",
  str_mission_desc_4204070 = "Um raio de luz ilumina repentinamente o campo de batalha, permitindo que você e seus aliados lutem sem restrições.",
  str_mission_desc_4204090 = "Você e seus aliados estão finalmente prontos. A escuridão não impedirá mais sua visão.",
  str_mission_desc_4204100 = "O que você está procurando... Onde poderia estar?",
  str_mission_desc_4204101 = "Encontre o ponto fraco, mire bem e concentre seus ataques!",
  str_mission_desc_4204115 = "Quem é mais poderoso: Axelia ou Sean?",
  str_mission_desc_4204120 = "Depois de muitas dificuldades, você finalmente encontra o Colossus que caiu em ruínas. A vitória está ao nosso alcance.",
  str_mission_desc_4204130 = "Imediatamente após copiar seus dados, o Colossus começa a se mexer. Poderia outra catástrofe estar próxima?",
  str_mission_desc_4204140 = "Um último poema, oferecido em seu nome... Um último adeus.",
  str_mission_desc_4205020 = "Você é forçado por Forsakin a lutar contra os soldados Illumina.",
  str_mission_desc_4205030 = "Você mais uma vez encontra sentinelas na entrada do laboratório.",
  str_mission_desc_4205040 = "Você e Vice não vão mexer os polegares enquanto o experimento continua. Aguarde o momento certo para reverter a situação...",
  str_mission_desc_4205041 = "Aproveite a oportunidade para derrotar o inimigo e escapar!",
  str_mission_desc_4205050 = "Sua resistência tem sido Eclipsites convocados por Forsakin em um duelo de fogo até a morte!",
  str_mission_desc_4205070 = "Separado de Vice, seu eu solitário não tem escolha a não ser obedecer a Forsakin. Você precisa seguir a vontade dela e se aventurar profundamente na Cidade Baixa.",
  str_mission_desc_4205080 = "Para localizar você e Vice, que está desaparecido há muito tempo, Carleen segue as dicas de Gronru para a Cidade Baixa.",
  str_mission_desc_4205090 = "Ainda procurando os arquivos, Forsakin não esperava defesas afiadas no arquivo de arquivos.",
  str_mission_desc_4205100 = "Encarregado de uma missão importante, Yingel finalmente descobriu o paradeiro de Vice, apenas para se deparar com um inimigo formidável antes do resgate...",
  str_mission_desc_4205101 = "Alguns inimigos o envolverão em uma luta longa e mortal, então seja cauteloso...",
  str_mission_desc_4205110 = "Yingel está travando uma dura batalha, enquanto Carleen chegou a Forsakin e tentará tirar você daqui.",
  str_mission_desc_4205120 = "Forsakin fica desequilibrado com o incêndio surpresa. Aproveite a oportunidade para derrotá-la e Helios!",
  str_mission_desc_4205130 = "Quando você está prestes a derrotar Forsakin, ela impede isso cortando a energia do portão principal...",
  str_mission_desc_4205140 = "Forsakin completou a atualização final para Helios. Vai ser uma luta brutal.",
  str_mission_desc_4206020 = "A primeira sessão é uma luta virtual através do Battle Simulator, e todos os participantes do exercício estão se preparando para isso com seriedade.",
  str_mission_desc_4206030 = "A segunda sessão são aulas de combate, com uma equipe de treinamento liderada por Wrath transmitindo o know-how de luta aos participantes do exercício...",
  str_mission_desc_4206040 = "Para mais créditos de curso, você, Vice, e Carleen decida solicitar licenças de simulador adicionais para aprimorar suas habilidades de combate.",
  str_mission_desc_4206041 = "Os inimigos parecem se alimentar da batalha! Tem que haver uma maneira de acabar com a luta!",
  str_mission_desc_4206050 = "Antes do início do exercício, Eclipsites de sabe-se lá onde surgiram de repente na cidade de Gannon. Livre-se deles o mais rápido possível.",
  str_mission_desc_4206060 = "A terceira sessão do Exercício Militar Conjunto é lutar contra verdadeiros Eclipsites em combate real. Os participantes prevalecerão contra tantos inimigos?",
  str_mission_desc_4206070 = "Ao chegar ao local de captura da bandeira, os esquadrões se dividem e vão para a Cidade Baixa. No entanto, seu esquadrão entra em uma luta inesperada contra os Eclipsites.",
  str_mission_desc_4206080 = "A batalha caótica continua e aquele esquadrão esquisito prova ser bem difícil...",
  str_mission_desc_4206090 = "Você mergulha mais fundo na Cidade Baixa até encontrar ao acaso um perigo ainda maior na forma de uma enorme monstruosidade parecida com uma aranha.",
  str_mission_desc_4206110 = "Você, Yingel, e outros se separaram para verificar Gannon. Com certeza, você se depara com Eclipsites que escapam pela brecha nas defesas!",
  str_mission_desc_4206120 = "Os intrusos do Eclipsite se espalham em pânico, aparentemente sem intenção de lutar. Você também sente a ameaça familiar de um certo Wraith...",
  str_mission_desc_4206121 = "Intrusos ainda estão presentes na cidade que devem ser eliminados o mais rápido possível.",
  str_mission_desc_4206130 = "Seguindo as trilhas do Wraith, você chega a um certo portão no nível mais baixo. Figerald está atrás de algo lá dentro. Pare ele!",
  str_mission_desc_4206140 = "Os peões estão todos fora do caminho. Agora vamos para Figerald, o Espectro!",
  str_mission_desc_4207020 = "Você e Vice chegam ao escritório dos Comandantes da Legião Illumina, esperando uma chance de mudar o rumo das coisas. No entanto, antes mesmo de vocês poderem falar, os comandantes já receberam ordens de missão e partiram...",
  str_mission_desc_4207030 = "Os cidadãos de Illumina estão agitados com o que vem acontecendo recentemente. Assim que você percebe isso, um anúncio ecoa pelas transmissões da Subcidade, proclamando a ascensão de um novo Grande Marechal...",
  str_mission_desc_4207031 = "Os Eclipsitas logo escaparão de onde estão confinados. Derrote-os para garantir a segurança do laboratório!",
  str_mission_desc_4207040 = "Tendo acabado de ser promovida a Grande Marechal de Illumina, Wrath já é designada para reforçar a frente de batalha em Crepúsculo. No entanto, enquanto se prepara para partir, ela parece não ter sentido nenhuma das alegrias esperadas ao se tornar a Grande Marechal...",
  str_mission_desc_4207050 = "Refletindo sobre o passado, Wrath iniciou inúmeros desafios contra Reinhardt, quase todos terminando em fracasso, incluindo a seleção final para Grande Marechal...",
  str_mission_desc_4207060 = "Joselyne lidera os feridos em direção à segurança. No entanto, ao saber da confiança vacilante dos soldados no campo de batalha, ela reflete sobre o que pode fazer por eles...",
  str_mission_desc_4207080 = "Com suas habilidades psíquicas, você percebe que o fluxo escuro predominante em Crepúsculo parece ser controlado por um comando central. No entanto, o principal inimigo neste centro ainda está envolto em mistério...",
  str_mission_desc_4207090 = "A chegada dos soldados Illumina interrompe momentaneamente as ações dos Eclipsitas, mas Forsakin parece ter detectado o segredo por trás da força aprimorada desses soldados...",
  str_mission_desc_4207100 = "Enquanto a batalha contra os Eclipsitas continua, uma onda de ações anormais se espalha entre os soldados Illumina. Surgem especulações de que os soldados possam estar sendo influenciados por algum inimigo agindo como comando central...",
  str_mission_desc_4207110 = "Preocupada com Axelia no campo de batalha, Yingel segue para o laboratório de Ulysses. Dentro destas paredes, ela testemunha um experimento cruel...",
  str_mission_desc_4207111 = "Os monstros nos pântanos bloquearam seu caminho. Derrote-os!",
  str_mission_desc_4207120 = "Enfrentando o lamaçal que se espalha cada vez mais e os ataques dos Eclipsitas, Wrath toma uma decisão resoluta - mergulhar na lama, em busca do comando central inimigo escondido nela...",
  str_mission_desc_4207130 = "Após o confronto com o inimigo do comando central, o corpo de Wrath gradualmente foge ao seu controle. Soroz especula que sua consciência foi engolida pela lama...",
  str_mission_desc_4207140 = "O esquadrão de Axelia está preso na lama há algum tempo. Neste momento, Axelia já perdeu a capacidade de atacar os Eclipsitas, mas seus lábios continuam murmurando dois comandos de ação especiais...",
  str_mission_desc_4208020 = "Com o Eclipsita de lama derrotado, você embarca em uma busca total pela localização de Wrath. No entanto, neste exato momento, mudanças inesperadas também começam a se manifestar entre os soldados da Illumina...",
  str_mission_desc_4208030 = "Um alívio inunda você com o retorno de Wrath, mas seus infortúnios deixam você perplexo. Posteriormente, o foco coletivo se volta para lidar com a situação dos soldados feridos...",
  str_mission_desc_4208040 = "A equipe de rastreamento liderada por Charon e Vice encontra uma resistência peculiar, impedindo-os de chegar à Zona Sombria. Enquanto isso, a bordo do trem, surge um passageiro misterioso...",
  str_mission_desc_4208041 = "A situação está ficando fora de controle. Os inimigos agora miram em você; por favor, proteja seus colegas de equipe.",
  str_mission_desc_4208050 = "Victoria liderou o grupo para evitar temporariamente a perseguição da força enigmática. No entanto, neste exato momento, a Bíblia Sangrenta traz uma nova revelação...",
  str_mission_desc_4208060 = "Enquanto Wrath procura por seus subordinados, um soldado desorientado a enforca pelo pescoço. Todos estão tentando fazê-la entrar na razão, mas ela ainda não consegue se decidir...",
  str_mission_desc_4208070 = "Joselyne implora ao Forte Lumo para abrigar os refugiados, mas encontra apenas recusa. Porém, justo quando os soldados feridos começam a atacar os inocentes, uma voz poderosa ecoa...",
  str_mission_desc_4208080 = "À medida que a operação de busca chega às barreiras de Crepúsculo, uma visão impressionante se desdobra diante dos olhos do grupo. E o mentor por trás de tudo isso, finalmente, aparece...",
  str_mission_desc_4208100 = "Com a lama dissipada, Crepúsculo fica apenas com paredes despedaçadas e ruínas. No entanto, diante desses destroços bagunçados, Leo e Joselyne parecem ter esperanças renovadas para o futuro da cidade.",
  str_mission_desc_4208110 = "Ao longo da linha defensiva da Illumina, Sharona lidera a 1ª Legião, tentando repelir os Eclipsitas. No entanto, a súbita inundação de atoleiros e ataques de companheiros soldados provocam pânico entre as fileiras...",
  str_mission_desc_4208111 = "Limpe os atoleiros com o reforço da artilharia!",
  str_mission_desc_4208120 = "Enquanto Forsakin lidera os pântanos em um ataque à linha defensiva de Illumina, um coro inquietante de rodas rangendo e cascos galopando ecoa na direção de Twilight...",
  str_mission_desc_4208130 = "A intensa batalha continua, com soldados Illumina desorientados lançando ataques incessantes contra o seu lado...",
  str_mission_desc_4208140 = "Enquanto os comandantes de Illumina analisam a situação atual, Forsakin, ao receber o sinal de retirada do Eclipse, decide desferir um golpe final nos soldados Illumina...",
  str_mission_desc_4001010_long = "Você tentou ativar a Colossus de novo, mesmo tendo falhado por 17 anos.\nVice, uma garota Aurorian, de repente apareceu na Colossus, enquanto você tentava novamente.\nVice prometeu te tirar dali uma vez que tivesse vencido os Eclipsitas com sua habilidade psíquica.\nSeria hora de finalmente escapar da Colossus?",
  str_mission_desc_4001020_long = "Você novamente venceu os Eclipsitas com suas habilidades.\nVocê e a equipe de Vice se tornaram amigos.\nNão dava pra acreditar que tivesse feito amigos antes mesmo de conhecer o mundo lá fora.",
  str_mission_desc_4001030_long = "Com o transmissor danificado, você foi cercado sozinho por Eclipsitas em grande número.\nTalvez fosse possível salvar a todos ativando a Câmara Estelar.",
  str_mission_desc_4001045_long = "Você perdeu sua consciência devido ao uso exagerado de sua habilidade psíquica para controlar a Colossus.\nOutro Aurorian, Srta. Blanc, se juntou a você.\nNo entanto, o sinal de ajuda atraiu alguns Eclipsitas.\nVocê se viu obrigado a encontrar uma rota de fuga.",
  str_mission_desc_4001050_long = "Você rapidamente achou o alvo de Charon, Zoya, uma engenheira, na estação base. \nAlém de Zoya, um jovem ainda estava desaparecido.\nVocê não podia deixar barato, por isso cruzou com um grupo de Eclipsitas na busca por ele.\nPor sorte, ele ainda estava vivo!\nVocê percebeu que “ele” estava machucado, e que na verdade, era uma menina.",
  str_mission_desc_4001060_long = "Finalmente, você entrou na Subcidade 28.\nCharon permitiu sua entrada e de forasteiros, apesar de sua rigidez.\nDepois de vencer aqueles que escaparam, você ancorou no porto de Soroz.\nApesar dos recursos limitados na subcidade, Colossus estava aos poucos se recuperando.\nCom um intervalo abençoado, você se sentiu aliviado e... desmaiou.",
  str_mission_desc_4001070_long = "Os Aurorians e você derrotaram o gigante Kraken, Eclipsita de alto nível, juntos.\nNão era hora de comemorar pois um exército forte de Eclipsitas o aguardava.\nPara uma fuga segura, visitar um mundo novo...\nVice decidiu tentar reativar a Colossus junto com você.",
  str_mission_desc_4001095_long = "Você e Vice controlaram a Colossus juntos. Assim que o motor ligou... Soroz, envolvido pela Aurora, finalmente acordou.",
  str_mission_desc_4001080_long = "O aquecimento era necessário, pois Soroz esteve dormente por 17 anos.\nContudo, você foi exposto sem defesas aos Eclipsitas.\nDefender a Colossus é a prioridade!",
  str_mission_desc_4001090_long = "A impossível operação de resgate foi muito difícil.\nJamais fuja e nunca desista. Pode fazer isso?\nO som de explosivos incomodou Vice e você.\nO que aconteceu no lado de Charon?",
  str_mission_desc_4001100_long = "A anormalidade se aproximava da área da qual Charon era responsável. \nCorra ao seu destino e prepare-se para lutar contra oponentes formidáveis!\nCharon e Dayna estavam corretas. Vocês estavam todos reunidos!\nExistia uma luz no fim do túnel:\nSoros estava ancorado em um porto próximo.",
  str_mission_desc_4001110_long = "Soroz, como esperança em adversidade,\nlhe ajudaria a fugir.\nNinguém sabia se existiriam desafios maiores.\nNão havia tempo para se preocupar com dificuldades imprevisíveis. Defenda os feridos e seus companheiros para ajudá-los a embarcar na Colossus.\nLevantar velas!",
  str_mission_desc_4001120_long = "Você foi gravemente ferido por Eclipsitas.\nAlguns companheiros caíram em batalha, outros lutavam desesperadamente pela vida.\nEra cada vez mais difícil aguardar por você.",
  str_mission_desc_4001130_long = "Soroz fugiu, para alegria geral.\nNo entanto, outro Eclipsita de alto nível, Nozard, apareceu na Colossus.\nBombardeados com batalhas, todos já estavam exaustos.\nAlguns companheiros sacrificaram suas vidas para salvar os demais...",
  str_mission_desc_4002015_long = "Já que estavam todos à salvo, Vice o convenceu a voltar para Illumina com ela primeiro.\nEnquanto você hesitava, Soroz, que esteve adormecido por 17 anos, foi obrigado a pousar devido a falhas.\nPor outro lado, Nozard sobreviveu e não desistiu de te caçar...",
  str_mission_desc_4002010_long = "O grande barulho da queda da Colossus atraiu inúmeros Eclipsitas.\nUma nova batalha se aproximava.",
  str_mission_desc_4002035_long = "Vice estava gravemente ferida por proteger você dos Eclipsitas enquanto vocês discutiam.\nNa zona crítica, um grupo de ladrões ditos como Sinsa derrotou os Eclipsitas.\nVocê foi salvo, mas eles diziam que a Colossus lhes pertencia.",
  str_mission_desc_4002020_long = "Outra batalha se aproximava. Mas você precisou contar com desconhecidos da Rediesel Wrench. \nEra ótimo saber que esses bandidos lutavam tão bem quanto os Aurorians!",
  str_mission_desc_4002030_long = "Outra batalha se aproximava. Mas você precisou contar com desconhecidos da Rediesel Wrench. \nEra ótimo saber que esses bandidos lutavam tão bem quanto os Aurorians!",
  str_mission_desc_4002040_long = "Será que Sinsa se questionou, ou agiu por impulso?\nNão cabe a você decidir, apenas observar.\nEle lhe guiou à base da Rediesel Wrench.\nEssa rua, Rua Cauda, estava repleta de desespero e corrupção.\nPor que ele lhe trouxe aqui?",
  str_mission_desc_4002050_long = "O mundo era hierárquico e cheio de cantos escuros e desconhecidos.\nVocê e Vice, na verdade, tinham um nova visão sobre a Rediesel Wrench...\nVocês descobriram ao menos um objetivo de Sinsa:\nExpurgar a resistência com a ajuda de Soroz.",
  str_mission_desc_4002060_long = "A batalha deixou o chão, mas todos questionaram como os Eclipsitas ainda conseguiam lutar com propósito.\nA presenta de Umbrahulk provou que estavam certos!\nAssim que os reforços de Illumina chegaram, os caras da Rediesel Wrench sumiram.\nMais uma vez, seu destino foi decidido por outra pessoa.",
  str_mission_desc_4002095_long = "Você retornou para a Subcidade 28 com Charon. Vice e Soroz estavam bem estabelecidos.\nA defesa era impenetrável, mas Charon e Hiiro ainda suspeitavam que os Eclipsitas sabiam como atravessar.\nDias depois, Vice se recuperou. O breve descanso foi interrompido por uma nova crise.\nA subcidade começou a tremer e o alarme foi acionado. O que aconteceu?!",
  str_mission_desc_4002070_long = "Os Eclipsitas atravessaram as defesas num ponto cego da subcidade, e tudo estava em perigo.\nA melhor maneira de proteger os feridos e os cidadãos era recuar. Apenas um plano de contingência seria viável.\nDúvidas se amontoavam, mas não havia tempo pra pensar...",
  str_mission_desc_4002080_long = "Sinsa e Eve já viveram antes na subcidade.\nEve também era reduzida a “tal aparência” lá.\nQual era a verdade?\nO que a história podia nos contar?\nAgora, restava a você seguir os passos de Sinsa e completar seus pedidos...",
  str_mission_desc_4002090_long = "Você foi alvejado por ondas de ataques Eclipsitas.\nSe continuasse assim, todos estariam em grande perigo!\nAcostumado com esse problema, você criou um plano: a última esperança era Colossus.",
  str_mission_desc_4002100_long = "Os Eclipsitas se juntaram em torno de Colossus. Melhor você recuar e destruir toda a informação da subcidade o mais breve possível.\nMas agora, não era hora de apertar O Botão Rubro!",
  str_mission_desc_4002110_long = "Todos estavam na Colossus, exceto Charon.\nVocê não podia abandonar Charon assim, mas estava exaurido das batalhas.\nO abandono cruel era inevitável, não importava a escolha a ser feita...",
  str_mission_desc_4002120_long = "O Botão Rubro foi pressionado. Recue agora!\nVocê derrotou Nozard que levantou de uma vez por todas, quebrou o cerco e fugiu.\nSubcidade 28 foi destruída. Enquanto lamentava por Charon...\nUm trem em alta velocidade saiu do fogo; seria Charon?!",
  str_mission_desc_4003015_long = "Antes dos reforços chegarem, você ouviu um pedido de ajuda por um jovem. Era um dos seus?\nVocê tentou aproveitar a pequena chance de descobrir a verdade, ainda que houvesse perigo!\nVice decidiu te apoiar dessa vez. Os Celestitas não precisariam mais lutar sozinhos.",
  str_mission_desc_4003010_long = "A recém-construída lápide estava no penhasco enquanto o sol brilhava.\nNem você nem Sinsa superaram o sentimento de saudade.\nNovas mudanças te surpreenderam. Tropas de Illumina quebraram o silêncio.\nVice e você retornaram para a equipe depois de lidarem com o inesperado ataque Eclipsita.\nOs caras da Rediesel Wrench foram embora, desaparecendo na selva...",
  str_mission_desc_4003020_long = "Mendelson, que protegia o Módulo de Tanque Pensante, foi atacado pelo Schummer.\nApesar dos esforços para resistir, seu corpo em frangalhos não conseguiria evitar seu destino.\nSem soldados, ele foi forçado a recuar e restou-lhe apenas pedir ajuda, enquanto corria.",
  str_mission_desc_4003030_long = "“O tempo está se esgotando”, avisou o jovem misterioso.\nAs escavações da Colossus nas Relíquias ES-0096-F7 chegaram a uma paralisação repentina. Hiiro também desapareceu.\nVocê e Vice ativaram a Colossus à força para procurar por seu superior.\nNão apenas para provar sua habilidade como comandante da Colossus\nmas também para salvar seus companheiros.",
  str_mission_desc_4003031_long = "A confirmar",
  str_mission_desc_4003040_long = "Membros da equipe de escavação foram assimilados pelos Eclipsitas!\nVocê precisou se recompor para lutar contra seus antigos companheiros.\nEnquanto isso, a barreira de relíquias Aurorian era corroída pelo poder sombrio.\nA Grande Aviduz anunciou com todo seu poder que ela expurgaria traições e vingaria a Mãe.",
  str_mission_desc_4003050_long = "Você não conseguiu salvar o último sobrevivente. A escuridão estava fadada a terminar assim.\nUma chuva de flores talvez salvasse sua alma...\nA cerejeira purificou seu corpo e plantou a fé Alma em sua consciência.\nEle revelou uma importante mensagem: “eles” ainda estavam aqui.",
  str_mission_desc_4003060_long = "Você finalmente encontrou Mendelson, gravemente ferido.\nEle foi capturado por seus próprios soldados devido ao grande poder de Schummer.\nBatalha iminente...",
  str_mission_desc_4003070_long = "A apresentação pareceu terminar secretamente em outro lugar.\nNo entanto, Schummer desejava um novo clímax, para injetar Fluxo Escuro infinito no núcleo da Colossus.\nVice percebeu algo, apesar da neblina.\nEra preciso improvisar. Intuitivamente, você encontraria uma maneira de encerrar a performance.",
  str_mission_desc_4003080_long = "Você tinha medo, mas morrer com dignidade era melhor que viver em desgraça.\nO Celestita foi exterminado. A prioridade era defender o futuro de todos!\nSchummer colocou as mãos no Módulo de Tanque Pensante. Era questão de tempo até...\nSupere o medo e dê um fim a tudo isso!",
  str_mission_desc_4003090_long = "A figura em sua mente agora estava à sua frente, estranha porém familiar.\nO jovem frágil era ECO das relíquias Colossus, Mendelson.\nEnquanto isso, Hiiro e Zoya estavam enterrados nos destroços.\nO rugido da morte da Colossus ecoou pelas ruínas...\nTinham de se apressar para o caso de outro colapso.",
  str_mission_desc_4003091_long = "A confirmar",
  str_mission_desc_4003100_long = "Muitos dos sistemas estavam fora do ar devido ao dano feito por Schummer.\nFoi difícil localizar Hiiro e Zoya. Teriam de dar um jeito de fugirem.\nVocê e Vice foram completar\numa missão mais importante com Mendelson.",
  str_mission_desc_4003110_long = "Você estava próximo ao Módulo de Tanque Pensante, e Schummer...\ntalvez esteja à sua espera.\nFaça-a parar! Afetada pela energia sombria, o corpo de Mendelson ficou cada vez mais fraco.\nTalvez... essa fosse sua última luta.",
  str_mission_desc_4003120_long = "Schummer foi embora, enquanto Tabaad lhe aguardava.\nGraças à ajuda de Hiiro, o corpo de Tabaad desapareceu na cerejeira.\nAcreditando na última visão, a vida de Mendelson terminou, deixando pistas:\nMódulo de Tanque Pensante, Unidade de Crescimento Autônomo, e Controlador de Chamas... serão os alvos de Schummer...",
  str_mission_desc_4003145_long = "Agora, nos arquivos de Lumópolis, o Módulo de Tanque Pensante está trancado em algum canto.\nOs olhos curiosos se aproximam, o que indica que os Eclipsitas atacarão Lumópolis em breve.",
  str_mission_desc_4004015_long = "Uma cidade gigante no céu apareceu à vista. Parece que seu alvo, outro Módulo de Tanque Pensante, estava ali.\nSeu velho inimigo, Schummer, notou Lumópolis. As coisas pareciam tristes.\nSua prioridade era convencer a Capitã dos Guardiões, Carleen.\nDe repente, sua conversa foi interrompida por um ataque surpresa...",
  str_mission_desc_4004010_long = "De acordo com os habitantes da Baixa Lumópolis, eles foram surpreendidos pelos Eclipsitas, quase sempre na área leste. Os\nGuardiões foram investigar a situação. Mas você escolheu checar a área oeste guiado pelos instintos de Carleen. O agente implantado na cidade sussurrou: Nós teremos a liberdade prometida se colocarmos as mãos naquela coisa.",
  str_mission_desc_4004020_long = "Os Eclipsitas foram vistos na área oeste! Os fugitivos estavam aterrorizando.\nDe acordo com Gertzurde, líder do esquadrão de Baixa Lumópolis, os cidadãos de fora da cidade precisavam de escolta.\nParece que ele era um famoso cavaleiro...",
  str_mission_desc_4004030_long = "As coordenadas providas por Soroz apontavam para os Jardins de Lumópolis, que eram cuidadosamente protegidos.\nQuando Darkover chegou,\na Grande Aviduz, à espreita na escuridão, colocaria as mãos no núcleo de Lumópolis.\nAntes da tempestade, você percebeu algo grande se aproximando...",
  str_mission_desc_4004040_long = "Darkover transformou todos os Guarda Lumo em Eclipsitas.\nAlgo que não deveria acontecer aqui. Baixa Lumópolis estava em perigo!\nVocê foi bloqueado pelos Soldados Lumo quando buscava Shire nos Jardins de Lumópolis.\nO importante era o Núcleo, e o destino de Lumópolis, então\nVice fez o seu melhor para convencer Carleen, a capitã dos Guardiões de Lumópolis, a apoiar sua missão.",
  str_mission_desc_4004050_long = "Alerta para a área oeste! Pareciam Eclipsitas de alto nível dessa vez!\nLocalize-os e extermine-os.\nCarleen parecia incomodada novamente.\nNão importa, você precisa seguir.",
  str_mission_desc_4004060_long = "Shelt se juntou com sua irmã para lutar, mas a sorte estava a seu favor.\nFumaça escondia as irmãs Eclipsitas, que iam em direção à residência \ndos Nobre Lumo, na Cidade Alta!\nPerigo! Guardiões, voltem agora para a defesa!",
  str_mission_desc_4004085_long = "No Arquivo de Lumópolis, Gertzurde está decodificando o Módulo de Tanque Pensante encriptado.\nShelt disse que atrairia os inimigos para a Cidade Alta para ganhar tempo.\nCarleen percebeu que seria uma aventura suicida se escapassem da Cidade Alta;\nPor isso, pediu à Raphaela que fosse na direção oposta enquanto ela localizava as irmãs Eclipsitas.",
  str_mission_desc_4004100_long = "Enquanto isso, Raphaela não encontrou o homem suspeito.\nNo lugar, encontrou Gertzurde, capitão do esquadrão, que acabara de completar a missão.\nEle segurava uma caixa coberta com tecido. O que ela continha?...",
  str_mission_desc_4004110_long = "Seguindo a trilha de sangue, você chegou num lugar perto da Cidade Alta. As irmãs Eclipsitas não podiam voltar.\nElas buscaram desesperadamente pela ajuda do homem misterioso, e receberam \ncomo opções derrotar inimigos ou sobreviverem.",
  str_mission_desc_4004120_long = "“Virarei um dente de leão... E voarei pra longe...”\nO poder e as mentiras do homem misterioso transformaram as irmãs em monstros.\nTal poder era um instrumento poderoso, mas uma tortura desumana. \nAs irmãs que tanto sofriam foram finalmente reduzidas a cinzas. A crise foi resolvida.\nA missão de Gertzurde foi cumprida. Por enquanto, Schummer possui o Módulo de Tanque Pensante completo...",
  str_mission_desc_4005015_long = "Os Comandantes de Legião de Illumina eram proibidos de desertar, por isso, não podiam ajudar.\nVocê devia, sozinho, seguir Schummer e localizar a Unidade de Crescimento Autônomo.\nPhilyshy, a Chefe de Inteligência, trouxe uma pista...\nEnquanto isso, Carleen requisitou uma ordem especial de Lumópolis –\nela iria atrás de Schummer com você.",
  str_mission_desc_4005010_long = "O número de Colossi caídas indicava o número de Celestitas sacrificados.\nAgora, você estava finalmente na relíquia Colossus dos 13 Sem-nome, mas eram apenas ruínas.\nO Diretor de Pesquisa de Illumina, Gronru, estava conduzindo pesquisas aqui.\nÉ verdade que a Unidade de Crescimento Autônomo caiu na Colossus!\nVocê precisava do poder Celestita, se quisesse retirá-la da Colossus.",
  str_mission_desc_4005020_long = "O interior da Colossus caída estava gravemente danificado, então o caminho até a Unidade de Crescimento Autônomo era tortuoso.\nA turbulência incomum revelou a chegada de Schummer.\nEla liberou o próprio poder sem dificuldades e humilhou aqueles inúteis.",
  str_mission_desc_4005060_long = "Mentes dos mortos eram um poema bem como uma canção, entrelaçando no vazio e se encontrando no tempo-espaço.\nO segundo módulo era o último presente que lhe dariam. Agora, a Colossus começava a brilhar novamente, após sua dormência.\nNo entanto, Schummer surgiu dos céus.\nPara proteger seus módulos, Gronru invocou o trono para cobrir sua fuga.",
  str_mission_desc_4005070_long = "O terminal tocou.\nEra uma mensagem de Gronru, ordenando que recuassem rapidamente, mas Schummer a interrompeu.\n“Volte para a Colossus abandonada dentro de 30 minutos e entreguem os módulos, ou Gronru estará morto”.\nSeguir as ordens ou salvar Gronru?",
  str_mission_desc_4005090_long = "Apenas 5 minutos antes do prazo limite.\nSoroz não aterrissou nem se foi. Você precisava decidir.\nEnquanto isso, Gronru não se resignava. Ela era mais forte do que imaginavam.",
  str_mission_desc_4005120_long = "Até mesmo para Celestitas, compreender o poder Eclipsita permitia tamanho poder?\nSchummer adquiriu com facilidade. Mas superando expectativas, ela manteve sua promessa. Mas também disse ter poupado sua vida por misericórdia e compaixão. Da próxima vez, seria uma batalha até à morte.",
  str_mission_desc_4006015_long = "Você precisava encontrar o Módulo de Controle de Chamas sem mais atrasos, mesmo sem o apoio de Illumina e Lumópolis;\nvocês decidiram ir até o distante Corredor Suspirante por conta própria.\nO Corredor Suspirante era um complexo labirinto, e assim que você se inquietou, o Senhor Sombrio, Soberano de Umbraton, lhe enviou um companheiro competente,\nSrta. Sheol, que lhe guiaria pelo labirinto...",
  str_mission_desc_4006010_long = "Suas operações de caça correram bem, mesmo apenas com apoio remoto da Sra. Sheol.\nBotas do exército se destacam das pegadas dos Eclipsitas...\nEra Gertzurde, o traidor que já foi o herói de Lumópolis.\nEle acreditou na mentira da morte de Shelt, então o ódio corroeu seu coração...",
  str_mission_desc_4006050_long = "Você parece ter encontrado o caminho certo para o Módulo de Controle de Chamas, mas não podia baixar a guarda ainda. Gertzurde parecia espreitar à frente. Seria essa sua batalha final com ele?",
  str_mission_desc_4006060_long = "Gertzurde, que estava determinado a se vingar de você, foi derrotado mesmo equipado do poder sombrio.\nEle finalmente entendeu que a pretensa verdade era uma mentira dita por Schummer e o homem misterioso, para controlá-lo.\nInfelizmente, era tarde demais. Dentes de leão se foram com o vento...\nGertzurde estava tão arrasado que decidiu te levar até Schummer.",
  str_mission_desc_4006085_long = "Décadas após a crise de Darkover acabar, Gertzurde foi eleito cavaleiro. Ele não era feliz em seu casamento com a filha de um nobre, então seu conto de Fadas não tinha final feliz, até conhecer Shelt, que era uma escolha errada.",
  str_mission_desc_4006070_long = "Eclipse sabia da traição de Gertzurde.\nGuiado por Gertzurde, o Módulo de Controle de Chamas estava na ponta de seus dedos.\nEsperando por você, estava seu velho amigo, Nozard, poderoso após ser transformado pelo homem misterioso.",
  str_mission_desc_4006110_long = "Você pressentia que Schummer lhe aguardava em seu destino.\nVocê sabia do identificador de módulos por Gertzurde, porém, Schummer devia saber também!",
  str_mission_desc_4006120_long = "Charon, que navegou até Other End sozinho, levou Schummer a acreditar que era reforço de Illumina.\nRelutante com os riscos, o homem misterioso e Schummer partiram, abandonando o corpo de Gertzurde.\nCarleen queimou seu corpo, e partiu com Shelt...\nEnquanto isso, Lumópolis enfrentava uma crise ainda pior...",
  str_mission_desc_4007015_long = "A Colossus negro de Schummer apareceu nos céus de Lumópolis.\nSem a proteção de escudos, a Baixa Lumópolis estava em perigo. Felizmente, um Comandante de Legião de Illumina próximo veio prestar ajuda.\nSchummer pagaria por seus atos, uma vez que a ameaça estivesse resolvida!",
  str_mission_desc_4007010_long = "Cada vez mais Eclipsitas se juntavam na Baixa Lumópolis.\nDada a falta de apoio dos soldados, todos agiam separadamente.\nNo entanto, você estava mergulhado novamente em batalhas sem-fim.",
  str_mission_desc_4007050_long = "Graças às suas táticas, as operações de resgate e de eliminação na Baixa Lumópolis foram cumpridas rapidamente.\nSua conexão com Soroz estava muito fraca, mas parecia estar segura.\nAssim que todos se acalmaram, Carleen soube do ataque na Cidade Alta!",
  str_mission_desc_4007060_long = "A Colossus negro era uma ameaça para toda a ilha flutuante,\nmas todos fugiram para a Cidade Alta a tempo e eliminaram Mara Sol.\nA batalha terminou com a arrogância de Schummer. Nesse instante, você ouviu um chamado de ajuda.\nA própria Colossus estava sob ataque?!",
  str_mission_desc_4007085_long = "Você tentou de tudo para se conectar com Soroz mas falhou.\nIgnorando o pior, sua prioridade era voltar pra apoiar Soroz imediatamente.\nQuando todo mundo estava perdido sem veículos,\nCarleen chegou voando com uma nave, salvando você, como sempre.",
  str_mission_desc_4007070_long = "Soroz estava acabado depois da invasão Eclipsita.\nA pior consequência era sabida, mas você acreditava que Soroz estava vivo.\nEncontre Soroz antes de ser achado por Schummer!",
  str_mission_desc_4007100_long = "Você finalmente sentiu Soroz após uma dura batalha.\nMas não era mais uma chamada, e sim uma mensagem repetida.\nSerá que... O pior havia acontecido com Soroz?",
  str_mission_desc_4007110_long = "Você não conseguia sentir Soroz fazia tempo,\ne a dor pulsante em seu coração era um lembrete dessa anomalia.\nEnfim, Schummer disse que Soroz já estava...",
  str_mission_desc_4007120_long = "Por Soroz, você batalhou contra Schummer, que só ficava mais forte!\nA descoberta mais surpreendente era que outro Eclipsita de alto nível, Forsakin, era um dos companheiros que antes pertencia à Illumina!\nDe surpresa, a Colossus Negro foi logo atacada.\nVivian planejou arriscar a própria vida para sua fuga.\nDepois do tremendo impacto que trouxe incorporalidade. O que você enfrentaria a seguir...?",
  str_mission_desc_4008015_long = "Um grito o acordou de um sonho estranho.\nVocê estava dentro de Aviduz com Vice, que nunca hesitou em te salvar.\nAgora você precisa achar um jeito de escapar...",
  str_mission_desc_4008020_long = "“Ninguém fica pra trás”.\nCom isso em mente, você decidiu salvar a Líder Vivian primeiro!\nEnquanto isso, a figura misteriosa ainda te guiava...",
  str_mission_desc_4008030_long = "Conforme você avançava, seu corpo parecia estranho.\nNo entanto, não havia tempo para verificar o problema, o tempo urgia para encontrar Vivian.\nEnquanto isso, você tinha certeza que Carleen estava fazendo seu melhor pra continuar...",
  str_mission_desc_4008060_long = "A anormalidade dentro de seu corpo não podia ser ignorada. Algo estava prestes a acontecer,\npois em batalha, até mesmo os Eclipsitas te ignoravam...\nO que realmente estava acontecendo?",
  str_mission_desc_4008070_long = "Conforme Curie abriu caminho, você finalmente chegou onde a Chefe Vivian estava presa,\ne onde Solfall, um poderoso inimigo, lhe esperava...\nApós derrotá-lo, a figura misteriosa mostrou sua verdadeira forma e lhe ajudou a se livrar do problema conhecido como \"semente\".",
  str_mission_desc_4008085_long = "Em Lumópolis, Carleen falhou em receber o apoio do Senhor.\nNo entanto, isso não abalou sua determinação em usar a arma suprema...\nNa sala de controle, Carleen decidiu ativar Dâmocles ela mesma!",
  str_mission_desc_4008090_long = "Ainda que Líder Vivian estivesse a salvo, não seria sábio escapar agora.\nEsse era o ponto de virada da batalha, e o grupo se tornou a força para atrapalhar a formação inimiga.\nVocê não podia partir... tinha que parar de defender e começar a atacar!",
  str_mission_desc_4008100_long = "A batalha estava esquentando, e Schummer finalmente sabia de suas ações.\nParecia que essa ardilosa batalha estava destinada a acontecer no núcleo da Colossus Negro... a ponte!\nEnquanto isso, Dâmocles também preparava a tempestade final...",
  str_mission_desc_4008130_long = "Diante da cobiçada Lumópolis, o que Schummer estaria pensando agora?\nSua mente estaria cheia do nostalgia, ou quem sabe de arrependimento?\nVocê deve continuar em frente... A fonte dos problemas está à frente!",
  str_mission_desc_4008140_long = "A batalha final na ponte. Os Eclipsitas no seu caminho foram logo aniquilados.\nSem nenhum conhecimento prévio de Dâmocles, Schummer logo sentiu seu poder destrutivo...\nCarleen iniciou o ataque do canhão de luz e, com sua ajuda, ela penetrou Aviduz.\nO vento negro finalmente caiu derrotado...",
  str_mission_desc_4008155_long = "Enquanto isso, conforme a batalha terminava...\nDiversas peças-chave, preparadas para guiar a direção do mundo, saíram dos bastidores e revelaram-se ao palco.\nUm furacão escuro do destino começou a se formar. Como você chegaria ao seu destino supremo?",
  str_mission_desc_4009015_long = "Após o Incidente com o Dâmocles, Carleen recebeu uma punição provisória, e a importante tarefa de descobrir a causa do incidente foi dada a você.\n O \"corpo\" de Schummer deve ser encontrado, e caso você queira reparar Soroz, este assunto deve ser resolvido.\n Por acaso, a Aviduz caiu naquele lugar familiar, mas estranho: Eraveil.",
  str_mission_desc_4009020_long = "A Eraveil que te esperava era muito diferente da vista em sua visão.\nEra estéril, sem vida, contaminada com uma energia estranha e infestada de Eclipsitas.",
  str_mission_desc_4009030_long = "Depois que a Colossus caiu em Eraveil, os membros da Rediesel Wrench se juntaram a você para encontrá-la.\nSinsa e Bopper esperavam conseguir alguns materiais dos destroços, mas acabaram se perdendo de seu grupo.",
  str_mission_desc_4009040_long = "Você e Sinsa se encontraram novamente sem querer, mas ele parecia não saber exatamente onde esteve.\nNo entanto, não era hora de conversar. A primeira coisa a fazer era começar a procurar a Aviduz...",
  str_mission_desc_4009050_long = "Embora a exploração estivesse mais fácil com a ajuda de Sinsa, o clima estava ficando mais frio a cada segundo.\nA única explicação era que este lugar havia se tornado um ninho de Eclipsitas...",
  str_mission_desc_4009070_long = "Você encontrou um distintivo provando que um dos Eclipsitas já foi um Aurorian.\nParece que o inimigo mutilado à sua frente já foi como seus companheiros Aurorians.\nVocê deve acabar com a dor dele.",
  str_mission_desc_4009085_long = "Recuperando-se das feridas dolorosas dentro de sua cápsula de cura, Schummer sonhou com seu passado.\nA Schummer do passado falou de sua determinação e desejo com fervor e esperou seu renascimento.",
  str_mission_desc_4009090_long = "Você sentiu tristeza e desespero emanando das profundezas de Eraveil.\nSerá que é uma ilusão ou a realidade? A Aviduz também estava chorando em agonia?",
  str_mission_desc_4009130_long = "Tendo derrotado os Eclipsitas em Eraveil, você finalmente estava perto de onde a Aviduz caiu.\nNo entanto, os membros da clandestina True Order também pareciam ter assuntos ali e estavam reunindo algo nas sombras...",
  str_mission_desc_4009140_long = "Ao se encontrarem novamente, Forsakin pareceu um pouco surpresa por você ainda não ter se \"transformado\".\nAntes que você tivesse a chance de acertar as contas, ela escapou.\nNo entanto, antes de fugir, ela deixou uma pista importante, finalmente confirmando que Schummer ainda estava viva.",
  str_mission_desc_4010015_long = "Enquanto isso, no Centro Médico de Lumópolis...\nPhilyshy foi visitar Vivian e a avisou que você estava perseguindo Forsakin.\nAs duas também falaram sobre a relação entre Forsakin e a Grande Marechal...",
  str_mission_desc_4010020_long = "Para continuar sua busca por Forsakin e encontrar Schummer, você entrou na Aviduz.\nEmbora a Aviduz tenha caído há muito tempo, seus destroços ainda emitiam uma poderosa quantidade de Fluxo Escuro.\nE o mais perturbador foi o fato de que os Eclipsitas dentro dela estavam todos fugindo com pressa, como se algo terrível estivesse despertando nas proximidades...",
  str_mission_desc_4010030_long = "Ainda se recuperando das feridas, Schummer acordou cedo e estava se alimentando de Eclipsitas para recuperar energia!\nMesmo que não entenda o motivo dela se corromper ainda mais, você deve seguir em frente e encontrar sua inimiga imortal!",
  str_mission_desc_4010070_long = "Sua inimiga caiu nos braços da morte mais uma vez.\nA indiferença cruel e imoral de Forsakin te levou a outro nível de irritação. Você deve encontrá-la e à Schummer!\nEnquanto isso, em sua busca, mais informações sobre o passado de Schummer vieram à tona...",
  str_mission_desc_4010085_long = "Naquele dia, dezessete anos atrás, Schummer se tornou o arauto da queda de Eraveil.\nEla emitiu o grito do caos em nome do Eclipse. Alguns foram forçados a aceitá-lo, enquanto outros lutaram até a morte tentando resistir.\nMas, no final, os Celestitas foram condenados. Ela usou o sangue recém-derramado para completar seu tão almejado objetivo: sua evolução sombria.",
  str_mission_desc_4010090_long = "Depois de vislumbrar o passado de Schummer, você viu que seu sonho com Eraveil refletia a tragédia daquela memória distante.\nA estrada da vingança já havia durado bastante. Era hora de encontrar Schummer e acabar com tudo isso.",
  str_mission_desc_4010130_long = "Forsakin finalmente levou Schummer a um caminho sem volta, forçando-a a passar por um grande avanço no poder...\nNo entanto, como resultado ela perdeu todo o controle da mente. Em um estado de completa loucura, ela apareceu diante de você mais uma vez.\nApenas um de vocês sairia desta batalha com vida.",
  str_mission_desc_4010140_long = "Você derrotou uma Schummer enlouquecida, mas parecia haver um fluxo infinito de poder dentro dela.\nPara recuperar a Semente, Forsakin drenou o poder de Schummer.\nEssa, que viveu para sua própria distorcida cruzada por justiça e renascimento, finalmente morreu em meio a uma maré de Eclipsitas...\nExatamente como seu próprio povo, muitos anos atrás.",
  str_mission_desc_4010155_long = "Com a ajuda das pessoas de Rediesel Wrench, todos conseguiram escapar da Aviduz e deixaram Eraveil.\nVocê também conseguiu conectar o Módulo de Tanque Pensante que obteve de Schummer com Soroz, e os reparos pareciam promissores até então.\nAgora você não conseguia deixar de se perguntar onde sua próxima aventura te levaria...",
  str_mission_desc_4101015_long = "Soroz tornou-se instável sem o Echo Template. Se isso durasse mais, o dano poderia acontecer. Você e Vice decidiram visitar uma Cidade Baixa localizada na fronteira da terra da Noite Eterna seguindo a liderança fornecida pelo Módulo Think Tank.",
  str_mission_desc_4101020_long = "Chegando em Undercity 80 na fronteira da terra da Noite Eterna, você percebeu que Eclipsites havia reivindicado este lugar como seu desde o abandono de Illumina. O intenso Darkflow tornou quase impossível usar Luminatics. Nessas circunstâncias, você inicia a investigação com cautela.",
  str_mission_desc_4101030_long = "Você e Vice avançaram mais fundo na Cidade Baixa. Vestígios de guerra podiam ser vistos por toda parte sob uma espessa camada de poeira acumulada ao longo dos anos. Nas ruínas, você descobriu alguns módulos Colossus descartados...",
  str_mission_desc_4101040_long = "A peça que poderia ser usada para reparar o Modelo de Eco de Soroz foi embutida em uma máquina na câmara central. Você se esforçou para tirá-lo, o que fez com que o núcleo de energia desta Cidade Baixa parasse. Sem energia, a Cidade Baixa começou a desmoronar e um Eclipsite de Alto Nível surgiu durante o colapso.",
  str_mission_desc_4101055_long = "Você e Vice enfrentaram o Eclipsite de Alto Nível com os fardos extras trazidos pelo Darkflow enquanto buscavam uma oportunidade de escapar. No entanto, o Eclipsite cortou completamente o seu caminho. Neste momento crucial, Reinhardt veio em seu socorro. Para sua surpresa, aquele Eclipsite de Alto Nível parecia ser um velho camarada dela.",
  str_mission_desc_4101060_long = "Reinhardt levou você a uma rota de fuga diferente em direção ao solo. Mas o Darkflow ficou mais pesado à medida que você subia – já era depois do anoitecer. A batalha só se tornaria mais difícil a partir daí.",
  str_mission_desc_4101070_long = "Sob seu questionamento contínuo, Reinhardt começou a recontar uma história do passado. Seus companheiros uma vez travaram uma árdua batalha com ela em Undercity 80. Ela saiu do cerco do inimigo para buscar ajuda, mas apenas para descobrir que Illumina os havia deixado para trás para salvar a maioria da população.",
  str_mission_desc_4101080_long = "Você alcançou o nível do solo na escuridão mais profunda logo antes do amanhecer. Forsakin e o Eclipsite de Alto Nível estavam esperando em silêncio. Reinhardt pediu ajuda a você. Ela queria dar uma última tentativa para trazer seu antigo camarada de volta.",
  str_mission_desc_4101090_long = "Forsakin despertou o ódio profundamente enterrado do High-Level Eclipsite e mudou sua aparência. Uma batalha mortal era iminente. Reinhardt sofreu ferimentos graves para protegê-lo. Nesta situação desesperadora, ela resistiu corajosamente...",
  str_mission_desc_4101105_long = "Ameaçados pelo exército Eclipsite, Vice e você trouxeram Reinhardt gravemente ferido de volta a Soroz e se dirigiram para a salvação da Illumina. No caminho, Reinhardt relembrou algo do passado. Algumas mudanças de grande importância pareciam estar se formando dentro da sólida Cidade Baixa da Illumina...",
  str_mission_desc_4201015_long = "Seguindo as pistas que você conseguiu obter, você partiu para Eraveil em busca da Base de Manutenção Colossus na esperança de encontrar uma maneira de devolver Soroz ao seu estado original. No entanto, as coisas não saem exatamente como o planejado...",
  str_mission_desc_4201020_long = "No caminho para Eraveil, Soroz é atacado por Eclipsites no que parece ser uma emboscada planejada. Durante a batalha, o ataque de Eclipsites quebra o painel de controle do Colossus, e Soroz começa a cair...",
  str_mission_desc_4201040_long = "Você cai em um vasto espaço na base de uma torre branca. De acordo com os dados de Soroz, este é o \"Tarmac\", então a base que você procura deve estar próxima. Hora de pegar o detector de metais e começar a explorar.",
  str_mission_desc_4201050_long = "À medida que você começa a procurar, alguns Eclipsites seguindo você silenciosamente cercam a Torre Branca. Para continuar a busca, você explode a entrada do Tarmac com Barton's ajuda e impedi-los de ir mais longe.",
  str_mission_desc_4201060_long = "Seguindo a entrada que você descobriu, você entra em uma vasta base abaixo de Eraveil, e você encontra muitos vestígios dos celestitas que viveram aqui antes, que você nunca soube que existiam.",
  str_mission_desc_4201070_long = "Depois de uma batalha feroz, você caiu inconsciente por falta de oxigênio. Por puro acaso, você se conectou com a IA que controla a base. Com sua ajuda, a ventilação foi ligada e você recuperou a consciência. Sob a orientação da IA, você continua explorando a base...",
  str_mission_desc_4201090_long = "Você chega a um vasto espaço na base, e há sinais de que essa área já foi conhecida como Zona do Exílio, e que os exilados aqui no passado eram celestitas. Aqui, você encontra um Lance Rifle que pertenceu a um Caelestite e o usa com sucesso para derrotar Eclipsites.",
  str_mission_desc_4201100_long = "Perseguido por um poderoso Eclipsite, você não tem escolha a não ser usar os dispositivos defensivos da base subterrânea para lidar com isso. Mas esses dispositivos não são apenas para atacar Eclipsites, eles também são perigosos para os Aurorianos. Vice também é ferido e cai em um estranho estado inconsciente conhecido como \"hibernação\".",
  str_mission_desc_4201115_long = "Para encontrar a cura para Vice e reparar Soroz, você continua sua exploração do núcleo da base. Lá, você se depara com uma máquina estranha - Sistema Circular - que só você, um celestita, pode usar. A partir desta máquina, você tem um vislumbre de alguns segredos desconhecidos.",
  str_mission_desc_4201120_long = "Você consegue encontrar um registro de um Auroriano despertando da hibernação no Sistema Circular. Mas devido à idade, você só consegue acessar fragmentos de informações. Você decide explorar as profundezas para encontrar mais pistas.",
  str_mission_desc_4201140_long = "À medida que o sistema da base de repente começa a reiniciar, você perde o controle da base e se torna o alvo de seu ataque. Os Guardiões da base acordaram de um sono profundo e você deve derrotá-los para recuperar o controle da base.",
  str_mission_desc_4201155_long = "À medida que você recupera o controle da base, a reinicialização é concluída, oferecendo acesso total. Em meio a tremores estrondosos, a torre começa a se erguer, revelando lentamente sua forma original. Criações de tecnologias antigas em todo Astra começam a ressoar estranhamente...",
  str_mission_desc_4202015_long = "Ao obter acesso administrativo à Torre do Retorno, você aprende sobre um dispositivo chamado \"Chord Link\" que pode salvar Vice. No entanto, como a Torre do Retorno caiu em desuso, não há informações sobre esse dispositivo no sistema, então você terá que ir até a área onde está localizado para investigar mais.",
  str_mission_desc_4202020_long = "À medida que você procura pelo link de acordes, Barton segue Forsakin's trilha para a torre. No entanto, ele se perdeu na vasta Torre do Retorno...",
  str_mission_desc_4202040_long = "No despertar do Bartona perseguição, Forsakin abandona seu plano de segui-lo e recorre à força. Você tem que jogar por tempo para quebrar o Controle de Acesso da Zona de Acordes sob Forsakinataque de.",
  str_mission_desc_4202050_long = "Você foge para a Chord Zone para evitar Forsakin, mas o ato de quebrar o Controle de Acesso aciona as defesas da Chord Zone. Com todas as armadilhas da passagem ativadas, você se depara com um obstáculo desafiador. Apenas quando as coisas vêm à tona, você aciona uma explosão de armadilha, parando brevemente Forsakin e entrando na zona de acordes.",
  str_mission_desc_4202060_long = "Para proteger Vice e derrota Forsakin, Barton, que está gravemente ferido, decide se transformar com o Chord Link. Durante este tempo, Forsakin comanda Eclipsites para quebrar o portão. Comprar Barton tempo, você enfrenta Forsakin.",
  str_mission_desc_4202070_long = "Como Barton completa a sincronização, ele ganha novos poderes e sai do Chord Link para se juntar a você na luta Forsakin. Como a maré virou, Forsakin foge no caos com Barton seguindo de perto...",
  str_mission_desc_4202085_long = "Bartono sucesso da empresa lhe garante, e você coloca Vice no Chord Link para sincronização. Através da vigilância da Torre do Retorno, você vê Eclipsites montando um grande exército do lado de fora da torre e Aurorianos de todos os lados lutando arduamente. Ao testemunhar isso, você decide expulsar esses Eclipsites de Eraveil com suas próprias mãos.",
  str_mission_desc_4202090_long = "Já que vai demorar um pouco Vice acorda, você e Carleen não têm escolha a não ser deixá-la no Chord Link para persegui-la Forsakin fora da torre. Neste momento, a cena do lado de fora da torre é de horror, com um número esmagador de Eclipsitas e Aurorianos lutando arduamente. É como se o tempo voltasse ao dia em que Eraveil foi atacado dezessete anos atrás...",
  str_mission_desc_4202100_long = "Sob os ataques implacáveis de Eclipsites, todos estão firmes, fazendo o possível para resistir. Então, o Eclipse revela seu trunfo - canhões Darkflow. Essas armas inesperadas colocam você imediatamente em desvantagem. A esperança de vitória parece estar desaparecendo rapidamente...",
  str_mission_desc_4202115_long = "Como todos do lado de fora da Torre do Retorno permanecem presos na batalha, a fim de virar a maré, Reinhardt sugere deixar alguns para trás como uma diversão enquanto ela e você emboscam os Eclipsites. Para proteger o Eraveil, você decide se unir a Reinhardt.",
  str_mission_desc_4202130_long = "Com Reinhardt e Forsakin travado na batalha, a maré ainda não mudou. Sentindo uma crise iminente, você decide voltar para a Torre do Retorno e obter acesso ao Anel Central para ativar a arma suprema da Torre do Retorno - o Acorde da Lei.",
  str_mission_desc_4202140_long = "Para ter acesso ao Core Ring, você enfrenta os Guardians sozinho, mas não consegue derrotá-los. Apenas quando você está prestes a ser derrotado, Vice, que acaba de se recuperar da hibernação, chega ao seu lado com seus novos poderes. Vocês dois trabalham lado a lado para derrotar os Guardiões e finalmente ativar o Acorde da Lei.",
  str_mission_desc_4202155_long = "O \"presente\" que o Mestre Francis deixou para você permite que você ative com sucesso o Acorde da Lei, mantendo todos os Eclipsitos longe da Torre do Retorno e encerrando a batalha. Incapaz de ativar novamente devido à falta de energia, a Torre do Retorno se torna um monumento à história, e todos se perguntam o que acontecerá com ela...",
  str_mission_desc_4203015_long = "O corpo de Vice de repente começou a emitir uma luz estranha, um possível efeito colateral do uso do Chord Link. Preocupado com a situação, você contata Vivian na esperança de que ela identifique a origem do problema.",
  str_mission_desc_4203020_long = "Preocupado com a segurança de Vice, você concorda em ajudar uma equipe de pesquisadores da Illumina a investigar as novas funções de Soroz. Durante a investigação, os pesquisadores descobrem uma enorme quantidade de dados de combate antigos; agora eles desejam que você acesse esses dados usando o Simulador de Batalha da Illumina e conduza mais pesquisas sobre eles.",
  str_mission_desc_4203030_long = "Você conduz uma série de testes usando o Battle Simulator, um dispositivo sofisticado usado para criar cenários de combate quase perfeitos. Depois de ver o simulador em ação, Reinhardt acredita que, por produzir batalhas ainda mais complexas, esse aparelho pode ser usado até para treinamento.",
  str_mission_desc_4203040_long = "Você entra no Battle Simulator mais uma vez, mas o ambiente interno foi alterado para uma Dark Zone. Dentro desta simulação sombria e hostil, seu objetivo é derrotar os Eclipsites e romper seu cerco.",
  str_mission_desc_4203050_long = "Usando o terreno para obter uma pequena vantagem, você finalmente derrota o último dos Eclipsites simulados. Espancados e machucados, você e seus aliados emergem do Battle Simulator após uma vitória difícil e encontram Reinhardt falando com os outros pesquisadores. Você ouve parte da conversa deles e descobre que Reinhardt viveu pessoalmente a batalha que você acabou de vivenciar...",
  str_mission_desc_4203060_long = "Você retorna ao simulador e o ambiente foi drasticamente alterado mais uma vez. Os aurorianos na simulação usam armas que você nunca viu antes e estão se defendendo desesperadamente de onda após onda de Eclipsites sedentos de sangue. À medida que caem para os monstros, um por um, o mundo virtual parece ficar cada vez mais sem esperança...",
  str_mission_desc_4203070_long = "Dentro da batalha simulada, as tragédias de uma guerra apocalíptica assaltam todos os seus sentidos. Soldados desesperados, Eclipsites furiosos e um monstro demoníaco como você nunca viu o cercam ... De repente, ocorre um erro no simulador e, quando você está prestes a cair no ataque cruel de Jormungand, Soroz insere sua consciência em a batalha e consegue puxá-lo para fora. Quando você recupera seus sentidos, fica chocado ao perceber...",
  str_mission_desc_4203085_long = "O Conselho Científico, uma organização que detém os segredos mais bem guardados da Federação Illumina, convidou você pessoalmente e Reinhardt para se encontrar com eles. Quaisquer que sejam seus motivos, eles são os mais capazes de entender a condição de Soroz agora. Ao entrar na sala de conferências, uma sensação de mal-estar iminente toma conta de você. De repente, Reinhardt gentilmente coloca a mão em seu ombro, quebrando a tensão opressiva que paira sobre a sala.",
  str_mission_desc_4203090_long = "No final da reunião, você e Algol chegam a um tipo de acordo. A pedido dele, você inicia um Mind Link com o Guardian One, uma máquina antiga em posse da Federação Illumina. Fazer isso beneficiará ambas as partes: os pesquisadores da Illumina terão a chance de observar as interações de um Caelestite com um dispositivo antigo, e você terá a chance de pedir ajuda ao Guardian One.",
  str_mission_desc_4203100_long = "No processo de estabelecer um Mind Link com o Guardian One, você percebe que, apesar de existir há incontáveis anos, essa inteligência artificial tem a personalidade de uma mera criança; como tal, só confiará naqueles que com ela interagem com honestidade e justiça. Depois de perceber sua preocupação com Soroz, o Guardian One imediatamente resolve ajudá-lo a resgatar a consciência de Soroz.",
  str_mission_desc_4203110_long = "O Guardian One leva você ao campo de batalha simulado em que Soroz está localizado. As consequências de uma antiga catástrofe de eras passadas estão diante de você, uma na qual os Eclipsites ainda vagam pelo planeta sem vida. Sabendo que a simulação está chegando ao fim, você deve procurar seu querido companheiro entre as ruínas de um mundo moribundo antes que tudo desmorone.",
  str_mission_desc_4203120_long = "Nos destroços de um mundo destruído, você finalmente encontra Soroz e acessa seu banco de dados. Familiarizado com as coisas ao seu redor, mas incerto do tempo ou lugar em que elas existem, seu estupor é finalmente quebrado quando o Guardião Um lhe diz que descobriu uma série de registros antigos dentro do terminal. Aqui, os celestitas estão longe de casa, vagando sem rumo...",
  str_mission_desc_4203130_long = "O Guardian One diz a você que, para reparar o Soroz, você deve primeiro inserir suas memórias e solucionar os erros em seus dados. Com a ajuda do Guardian One, deve ser uma tarefa bastante simples. Ao entrar nas memórias de Soroz, você vê mais e mais registros do terminal. Neles, os celestitas parecem estar diminuindo em número...",
  str_mission_desc_4203140_long = "Com a ajuda do Guardian One, você conseguiu limpar os erros no banco de dados de Soroz. Ainda pensando nos registros do terminal, você decide acessá-los novamente. Dentro dos registros, você testemunha um milagre: sob os cuidados dos Caelestitas, os Colossos nascem e adquirem consciência. Após esse breve milagre, vem uma longa espera, um período de tempo tão longo e monótono que requer cada grama de seu foco para chegar ao fim. De repente, uma cena familiar se desenrola diante de você: Eraveil.",
  str_mission_desc_4203155_long = "Depois de sair do mundo virtual, você retorna à sala de conferências mais uma vez. O Conselho Científico começou a discutir os eventos que acabaram de testemunhar. Eles acreditam que Soroz está operacional mais uma vez, mas concluíram que a sensibilidade do Colossus nada mais foi do que o resultado de um acidente. Para realmente restaurar a consciência de Soroz, você deve viajar para um lugar ainda mais distante...",
  str_mission_desc_4204015_long = "Confiado com o Fragile Combat Cyborg do Conselho de Ciência, sua próxima missão é fazer contato com as tropas Illumina estacionadas na cidade de Twilight. Lá, você deve trocar o andróide pelos recursos necessários para restaurar a consciência de Soroz. Você nunca ouviu falar desta cidade, que está situada nas linhas de frente da Illumina; para sua surpresa, você encontra Carleen lá em uma missão externa.",
  str_mission_desc_4204020_long = "A cidade de Twilight, localizada perto das Ruínas de Aurora e na fronteira com a zona da Noite Eterna, é um caldeirão de diferentes facções militares. Os Lumo Knights estacionados aqui já fizeram contato com Carleen; parece que Beretta e Yingel têm dois entendimentos muito diferentes deste lugar remoto e isolado. Conforme os Eclipsitas iniciam seu ataque, o frágil objeto em sua mão começa a emitir um som estranho...",
  str_mission_desc_4204030_long = "Um som estranho desperta você de seu sonho, e Soroz é quase \"removido\" por Sean. Acontece que Sean saiu correndo de Crepúsculo depois de receber uma mensagem sobre sua chegada há algum tempo. O plano dele era dar-te as boas-vindas ao mesmo tempo que realizava o seu trabalho de \"remoção\" habitual, que inclui limpar os Eclipsites da área à volta de Twilight, bem como quaisquer outros invasores suspeitos. Para um oficial de base como Sean, esta é apenas uma prática comum.",
  str_mission_desc_4204040_long = "Quando Axelia, Yingel, e Sean se cumprimentam, você percebe que os três têm uma história em comum. Eles explicam que são \"graduados\" do Programa Phospherus, um programa liderado pelo Conselho de Ciências com o objetivo de transformar crianças em super soldados. Embora os três tenham crescido muito desde então, eles ainda brincam e riem um com o outro como faziam quando crianças.",
  str_mission_desc_4204050_long = "Apesar do conflito selvagem em torno de Crepúsculo, seus moradores estão mais preocupados em se abrigar de um desastre natural iminente. A sobrecarga da aurora ameaça ficar fora de controle, e todos estão procurando desesperadamente abrigo para enfrentar a tempestade de energia iminente. Os Eclipsitas aproveitam o pânico generalizado e começam a atacar indiscriminadamente. Assim que você decide entrar na briga e salvar os habitantes da cidade, descobre que os reforços já chegaram na forma de um regimento de soldados de Lumopolis: os Ironthorn Knights.",
  str_mission_desc_4204060_long = "Diante de probabilidades aparentemente intransponíveis, os Ironthorn Knights facilmente quebram as fileiras dos Eclipsites antes de atacá-los. Depois de ver as incríveis proezas de combate de Leo em ação, você decide ajudar os cavaleiros a afastar os Eclipsites restantes. Assim como as marés parecem mudar a seu favor, no entanto, uma nova e ainda mais cruel ameaça surge...",
  str_mission_desc_4204070_long = "Uma nova onda de Eclipsites entra no campo de batalha, e os Lumo Knights são incapazes de se defender de seus ataques enquanto também protegem os habitantes da cidade. Você foge da linha de frente para defendê-los, mas os Eclipsitas são implacáveis em seu ataque. Assim que você atinge seus limites, uma jovem aparece de repente no meio da batalha; com uma luz sagrada e ofuscante, ela dissipa instantaneamente todos os Eclipsites nas imediações. Com os habitantes da cidade seguros, você volta à luta sem hesitar e, por fim, reivindica a vitória. Depois, a misteriosa garota conhecida como Joselyne convida você para jantar com ela em Crepúsculo.",
  str_mission_desc_4204085_long = "Joselyne leva você a um restaurante em Crepúsculo e conta mais sobre a cidade: sua história, seus problemas e, o mais importante, seus laços com um antigo e perdido Colossus. Depois de terminar sua refeição, você retorna ao Illumina Researcher, que o ajuda a restaurar totalmente a consciência de Soroz, mesmo que apenas temporariamente. Nesses breves momentos, Soroz aponta para um determinado local: uma Cidade Baixa nas profundezas da Zona Escura, onde o antigo Colossus está adormecido...",
  str_mission_desc_4204090_long = "Você decide viajar para o local que Soroz mencionou e recebe o apoio de Illumina e Lumopolis, bem como da recém-conhecida Joselyne. Depois de ver seu impressionante poder no campo de batalha, a ameaça dos Eclipsitas parece muito menos assustadora do que antes.",
  str_mission_desc_4204115_long = "Você e seus aliados avançam mais fundo nas ruínas. Desconfiado do grande número de Eclipsites perambulando pela área, seu grupo prossegue com o máximo de cautela. Neste momento, porém, Sean decide desafiar Axelia para uma disputa de força: quem derrotar mais Eclipsites é o vencedor e o mais forte dos dois.",
  str_mission_desc_4204120_long = "Você finalmente chega à Ponte do Colosso e começa sua busca pelo módulo necessário. Ao encontrá-lo, no entanto, você descobre que o módulo há muito se fundiu ao Colosso; removê-lo à força só causaria mais danos. Axelia então intervém e fornece a você um dispositivo que pode copiar os dados do módulo, mas diz que levará algum tempo...",
  str_mission_desc_4204130_long = "Depois de se defender do ataque dos Eclipsites, o dispositivo de Axelia finalmente termina de copiar os dados do módulo. Assim que seu grupo decide evacuar, o Colossus começa a roncar violentamente; está prestes a sair do controle? Para pacificar o Colosso e proteger os assentamentos perto das ruínas, você decide iniciar um Mind Link com o Colosso...",
  str_mission_desc_4204140_long = "Parece que o estrondo não foi causado pelo Colosso... Então, o que foi responsável por isso? Depois de estabelecer um Mind Link com o Colossus, você descobre que um grande número de Eclipsites se reuniu fora dele; dentro de suas fileiras, você sente a presença de uma entidade extremamente poderosa...",
  str_mission_desc_4204155_long = "Você volta para Twilight com Axelia e os outros a reboque e se despede. Com seus preciosos dados finalmente em mãos, você viaja de volta para Illumina. Só o tempo dirá se esses dados realmente ajudarão a restaurar Soroz; tudo o que você pode fazer é esperar. É neste momento que você recebe um convite do alto escalão de Illumina, um pedido para viajar para uma cidade subterrânea escondida onde ainda existe outro Chord Link...",
  str_mission_desc_4205015_long = "Contenção Vice refém, Forsakin está forçando você a ir com ela, aparentemente após um Chord Link secretamente descoberto por Illumina, com a intenção de completar os dados do experimento através Vice.\nEm outra frente, a batalha em Crepúsculo se intensificou à medida que Leo envia sinais de socorro para Lumopolis e Illumina.",
  str_mission_desc_4205020_long = "Para completar o experimento, Forsakin o coage a lutar contra os soldados Illumina e atrasá-los. Só espero que ela cumpra sua promessa de não matar ninguém.",
  str_mission_desc_4205030_long = "Você chegou ao destino, onde Forsakin, que conhece os arredores, chamou o Instituto X que ela construiu! Antes que você possa refletir mais, ela quer Vice para iniciar o Chord Link! O que vai acontecer?",
  str_mission_desc_4205040_long = "Forsakin não está satisfeito com o resultado da operação do Chord Link. Você e Vice tente emboscá-la, apenas para ela convocar uma multidão de eclipsitas para se opor a você.",
  str_mission_desc_4205041_long = "...",
  str_mission_desc_4205050_long = "Você não é páreo para Forsakin e lutou sem sucesso. Helios aparece ao lado de Forsakin e isola você de Vice, forçando vocês dois a obedecer.\nEnquanto isso, Ulisses chama Yingel para uma reunião secreta e a incumbe de uma missão especial.",
  str_mission_desc_4205065_long = "No Crepúsculo sitiado, Leo recebe não ajuda, mas um convite para um Exercício Militar Conjunto, que ele aproveita para alertar o mundo sobre a ameaça da Zona Cega.\nEnquanto isso, Illumina e Lumopolis também começam a se preparar para o exercício, como se o cérebro por trás dele jurasse vê-lo até o fim...",
  str_mission_desc_4205070_long = "Depois que Forsakin separou você e Vice, você não tem como contatá-la além de um comunicador. Você continua enquanto Forsakin começa a vasculhar os arquivos em busca de informações sobre o Programa Phospherus.\nEnquanto isso, Yingel encontra-se com oficial de inteligência Anatoli com uma ordem secreta, parece que seu objetivo é o Instituto X também.",
  str_mission_desc_4205080_long = "Para encontrar a saudade de você e Vice, bem como descobrir o que realmente está por trás do exercício conjunto, Carleen chega em Illumina para falar com Gronru, que a aponta para o Instituto X, onde ela conhece Yingel por acaso e fica sabendo da crise aqui.",
  str_mission_desc_4205090_long = "Forsakin tenta obter mais informações sobre o Programa Phospherus, mas acidentalmente aciona as defesas. Depois de derrotá-los, ela muda as palavras-chave e acessa os arquivos com sucesso.",
  str_mission_desc_4205100_long = "Você perde contato com Vice quando o comunicador ficar sem energia, mas não antes de dar Yingel e outros tempo para descobrir a localização exata de Vice.\nNo entanto, quando Yingel se aproxima, ela percebe que um inimigo poderoso está guardando Vice—Hélios.",
  str_mission_desc_4205101_long = "...",
  str_mission_desc_4205110_long = "Yingel e Helios estão presos em uma luta feroz. Ela também percebe que Forsakin provavelmente sentirá a batalha.\nEnquanto isso, Carleen chega até você. Ela tenta derrotar Forsakin e tirar você daqui, apenas para se envolver em uma batalha difícil.\nA visão desesperada de Helios se unindo a Forsakin sugere Yingel para incinerar corajosamente o Chord Link...",
  str_mission_desc_4205120_long = "O chamado inferno acaba por ser uma mera ilusão por Yingel, mas muda o rumo da batalha e dá vantagem ao seu lado. Yingel também tenta convencer Forsakin de que Reinhardt nunca a abandonou após o incêndio no laboratório e que sua suposta vingança foi equivocada desde o início.",
  str_mission_desc_4205130_long = "Recusando-se a desistir, Forsakin corta a energia do laboratório e fecha a porta, ganhando tempo para si mesma e para o Chord Link para atualizar Helios.\nEnquanto isso, o motivo de Ulysses está lentamente vindo à tona, já que ele tem um grande interesse no resultado do experimento de Forsakin...",
  str_mission_desc_4205140_long = "Finalmente, Forsakin mescla três melhorias diferentes em Helios, alterando drasticamente sua aparência. Após o fim da batalha, Helios surpreendentemente recupera seus sentidos, embora com uma memória um tanto fragmentada.\nEnquanto isso, Wrath e Reinhardt chega para enfrentar Forsakin, mas ela ainda consegue fugir.",
  str_mission_desc_4205155_long = "Ninguém consegue encontrar Forsakin no Instituto X e especula que ela pode estar escondida perto de Gannon. Enquanto isso, o Exercício Militar Conjunto começa conforme planejado naquela cidade, quando representantes de vários poderes se reúnem e lutam pelo título de melhor exército.\nMas na sombra de Gannon, Forsakin e Helios espreitam...",
  str_mission_desc_4206015_long = "O exercício começa, atraindo equipes de Gannon de Lumopolis, Illumina e Twilight, bem como seu trio e outro esquadrão misterioso.\nVivian informa sobre as regras e indica que o vencedor terá a honra de desafiar o Grande Marechal.\nEnquanto isso, no canto da cidade, Forsakin aguarda outros membros do Eclipse para resgatá-la e Helios.",
  str_mission_desc_4206020_long = "O primeiro é o conhecido Battle Simulator para que todos possam reviver campanhas árduas do passado. Muitos sofrem derrota contra todas as adversidades, exceto o esquadrão de Leo de Crepúsculo, que obtém uma vitória milagrosa.",
  str_mission_desc_4206030_long = "Em seguida, vem a parte da sala de aula, na qual é possível trocar os créditos do curso com base nas notas e no desempenho por materiais. Assim, sob a tutela de Wrath, todos mergulham na fina arte da \"briga\"...",
  str_mission_desc_4206040_long = "Um treinamento supostamente inofensivo é sabotado e quase termina em desastre. Acho que a competição entre os esquadrões não é tão amigável, afinal.\nEnquanto isso, dado Leo e o excelente desempenho de Yingel, você decide se inscrever para sessões extras de simulador, mas alguém manipula isso também...",
  str_mission_desc_4206041_long = "...",
  str_mission_desc_4206050_long = "Para os Eclipsites surgindo do nada em Gannon, Leo e Zhao vão além de sua autoridade para comandar os soldados Illumina para uma resolução. Wrath não fica muito entusiasmado depois de descobrir, mas passa a apreciar o talento de Leo.\nEm uma conversa, Wrath também descobre o desespero em Crepúsculo e percebe que os superiores parecem estar censurando as notícias...",
  str_mission_desc_4206060_long = "As lições avançam para o combate real no Exercício Militar Conjunto. Sob seu comando, todos derrotam todos os adversários por meio de uma aliança temporária, levando o evento ao segmento final: Capture the Flag.\nTodos começam a gastar os créditos do curso ganhos em equipamentos e adereços em antecipação à grande batalha para capturar a bandeira na Cidade Baixa.",
  str_mission_desc_4206070_long = "Indo para a Cidade Baixa em busca da bandeira, você, Carleen, e Vice estão planejando estratégias quando aquele esquadrão misterioso de Umbraton chega com um bando de Eclipsites a reboque...",
  str_mission_desc_4206080_long = "Você finalmente pôs fim aos Eclipsites após uma batalha caótica, mas o esquadrão Umbraton que começou o problema se recusa a entrar na Cidade Baixa com você, como se eles tivessem sua própria missão.\nEnquanto isso, os dois esquadrões mais fortes, Team Leo e equipe Yingel, comece a lutar entre si em algum lugar.",
  str_mission_desc_4206090_long = "Com o esquadrão misterioso aparentemente manipulando sua rota, você se depara com um perigoso monstro aranha.\nApós uma dura batalha, você corre para onde está a bandeira apenas para encontrar a luta entre a equipe Leo e Equipe Yingel acabou, com o vencedor sendo - Equipe Yingel.",
  str_mission_desc_4206105_long = "Equipe Leo está muito contente em ser o vice-campeão, já que o fizeram como um favor em troca de Illumina enviar reforços para Crepúsculo.\nEnquanto isso, Ulysses promove o plano para atingir seu objetivo por meio das ações de Forsakin em Gannon.\nDe fato, no local para lutar contra o Grande Marechal, Yingel recebe a notícia de uma invasão de Eclipsite na cidade. Você, Leo, e outros decidem ajudá-la no assunto.",
  str_mission_desc_4206110_long = "No confronto contra o Grande Marechal, Axelia exibe um nível incomum de poder e um desejo de morte. Reinhardt também sente algo estranho na partida de exibição.\nEnquanto isso, o desvio de Eclipsites libera Forsakin e Helios para escapar de Gannon por uma passagem secreta.",
  str_mission_desc_4206120_long = "Os Eclipsites em Gannon parecem estar chamando sua atenção de propósito, mas você não pode simplesmente interromper e deixá-los correr soltos também. Enquanto isso, você também sente a presença de Figerald the Wraith.\nNa arena, o ataque quase suicida de Axelia está começando a preocupar Reinhardt.",
  str_mission_desc_4206121_long = "...",
  str_mission_desc_4206130_long = "Reinhardt concede apenas para parar Axelia de seus próprios ataques suicidas, mas isso também se encaixa no plano de Ulisses.\nVocê, Leo, Yingel e outros correm para o local do Wraith, onde o mainframe do Guardian One é mantido!\nEnquanto isso, Forsakin e Helios chegam ao ponto de encontro apenas para descobrir que Esien já enviou soldados para lá. Eles percebem que o Eclipse os armou.",
  str_mission_desc_4206140_long = "Rebaixado a um mero peão sacrificial pelo Eclipse, Figerald é completamente derrotado e detido. Mas outro Wraith desconhecido tomou o núcleo do Guardian One e não há nada que alguém possa fazer sobre isso.\nQuanto a Forsakin, ela escapa ilesa quando Helios fica para trás para cobrir a fuga.\nDe volta à arena, Ulysses revela que o Comitê encontrou evidências de Reinhardt abrigando Forsakin em sua residência, colocando o Grande Marechal sob prisão na frente de todos.",
  str_mission_desc_4206155_long = "E é aqui que as coisas estão. Mesmo se você encontrar Reinhardt ser afastado do serviço uma pílula difícil de engolir, ainda é um fato.\nQuanto a Ulysses, ele está muito contente em interceptar os resultados do experimento de Forsakin, mas o Wraith capitalizando a oportunidade de roubar o Guardian One estraga a operação.\nO que vai acontecer com Reinhardt? E que inimigos desconhecidos jazem na sombra?",
  str_mission_desc_4207015_long = "A Federação Illumina está em andamento com seu terceiro julgamento público de Reinhardt sob acusações de traição. Enquanto você e Vice esperam do lado de fora da câmara de interrogatório, eventualmente chega a notícia de que Reinhardt foi destituída de seu título de Grande Marechal e condenada à prisão. A notícia deixa vocês dois pensando na possibilidade de uma reviravolta monumental no horizonte.",
  str_mission_desc_4207020_long = "Enquanto vocês se encontram confusos com a situação atual, Vivian, correndo apressadamente, chama Vice à parte, falando de uma missão imediata em suas mãos. Você chega à Estação Illumina e descobre que acompanhando Vice nesta missão não está apenas Charon, mas também três competidores que afirmam vir de Umbraton. Ao ouvir isso, uma sensação de inquietação toma conta do seu coração.",
  str_mission_desc_4207030_long = "Enquanto você está perdido em pensamentos sobre quem poderia guiar o caminho de Illumina, a transmissão de repente anuncia a nomeação de Wrath como o novo Grande Marechal. Em meio ao seu espanto, Leo corre para informá-lo sobre a invasão dos Eclipsitas em Crepúsculo. Ele implora para você pilotar o Colosso e acompanhá-lo para prestar ajuda. Enquanto isso, dentro de um certo laboratório em Illumina, um plano secreto está silenciosamente em andamento.",
  str_mission_desc_4207031_long = "—",
  str_mission_desc_4207040_long = "Sob os olhares atentos dos espectadores, a recém-nomeada Grande Marechal, Wrath, lidera as novas forças militares para se reunirem na estação, ao lado da avançada máquina de guerra, Engine VII. Embora Wrath agora esteja na posição que tanto desejava, ela sabe que ainda não triunfou sobre Reinhardt de forma justa. Pensando nisso, memórias de seus desafios passados contra Reinhardt começam a surgir no coração de Wrath.",
  str_mission_desc_4207050_long = "Com uma clara compreensão de sua própria força, Wrath há muito tempo antecipava os resultados da seleção final do Grande Marechal. Apesar de finalmente ocupar o lugar de Reinhardt, não era o caminho que ela esperava. Portanto, Wrath faz uma resolução interna de manter temporariamente a posição de Grande Marechal até o retorno de Reinhardt, comprometendo-se a superar seu papel em todos os aspectos possíveis.",
  str_mission_desc_4207060_long = "Impulsionados pela motivação e encorajamento de Joselyne, os soldados enfrentam corajosamente o ataque dos Eclipsitas. Enquanto isso, você e Leo finalmente chegam à entrada de Crepúsculo. Embora Leo esteja relutante em deixar você se juntar a esta batalha desesperadora, seu papel vantajoso como um Caelestite e piloto do Colossus o convence do contrário. No final, é o seu reforço que reacende a moral dos soldados no campo de batalha.",
  str_mission_desc_4207075_long = "Planejando solicitar apoio de Lumópolis, Zhao inadvertidamente se torna prisioneiro dos subordinados de Istvan. No Tribunal Real de Lumópolis, Schwartz segura vários pedidos de ajuda em suas mãos, enquanto os nobres debatem se devem enviar reforços. No final, Schwartz ordena que as tropas de apoio mantenham sua posição na Fortaleza Lumo, evitando envolvimento nas operações militares de Illumina.",
  str_mission_desc_4207080_long = "Com o ataque dos Eclipsitas aumentando em intensidade, até mesmo o experiente Leo se vê sobrecarregado. Justamente quando o grupo debate entre um ataque ousado ou uma retirada contínua, Wrath lidera a Legião da Guarda Illumina para o campo de batalha, mudando o rumo da batalha em Crepúsculo.",
  str_mission_desc_4207090_long = "Forsakin fica ciente das \"Sementes\" implantadas nesses soldados, projetadas para melhorar suas habilidades de combate. Apesar de seu descontentamento com Ulysses por roubar suas descobertas experimentais, ela percebe que os formidáveis Eclipsitas trazidos por Wraith estão a favor de suas ações subsequentes. Enquanto isso, você sente o aumento do enorme Fluxo Escuro, mas ainda está alheio ao fato de que o pesadelo no Crepúsculo está apenas começando.",
  str_mission_desc_4207100_long = "Ao investigar as anormalidades entre os soldados Illumina, Leo e Wrath têm uma discussão acalorada sobre problemas dentro das fileiras de suas forças. Com a esperança de descobrir a causa das anomalias dos soldados, Wrath busca sua ajuda. Enquanto você mergulha na consciência de um soldado corrompido e encontra um pântano sem limites dentro dele, no mundo real, Crepúsculo também sofre a incursão implacável de lama e Eclipsitas.",
  str_mission_desc_4207110_long = "Ao testemunhar o terrível destino dos soldados sendo abatidos pelos Eclipsitas durante o experimento, Yingel finalmente percebe o verdadeiro propósito do \"Programa Phospherus\": Eles estão implantando \"Sementes\" nos Aurorians e selecionando soldados excepcionais através do combate contra os Eclipsitas! Justo quando Yingel tenta interromper o experimento, um sujeito fora de controle de repente lança um violento ataque contra eles.",
  str_mission_desc_4207111_long = "—",
  str_mission_desc_4207120_long = "Após uma investigação minuciosa do campo de batalha ao lado de Wrath, você gradualmente desvenda por que os soldados Illumina são propensos à influência da lama. Enquanto isso, a lama implacavelmente se estende em direção a Twilight, e o inimigo que atua como centro de comando aproveita a oportunidade para lançar um ataque. Com Wrath liderando, você assume o comando no campo de batalha, mas acidentalmente é pego pela lama.",
  str_mission_desc_4207130_long = "Ao assistir Wrath avançar imprudentemente no meio dos Eclipsitas, você decide usar um Force Boost para entrar em sua consciência e despertá-la de dentro. De uma câmara do conselho suprimida à cidade de Gannon encharcada de chuva, e a visão de Reinhardt deitado em uma mesa de operação... Finalmente, em meio às cenas sempre em mudança da consciência de Wrath, você consegue localizar sua presença.",
  str_mission_desc_4207140_long = "Você e Wrath finalmente localizam o último esquadrão das forças Illumina. Encorajada pelas palavras de Wrath, Axelia gradualmente recupera sua mobilidade. Após sua busca extensa, o principal inimigo se revela, enquanto Leo chega, liderando os Cavaleiros da Expedição. No entanto, para proteger sua equipe da influência corruptora da lama, Wrath decide enfrentar o inimigo sozinha.",
  str_mission_desc_4207155_long = "Há apenas alguns dias, Wrath recebeu um aviso do Comitê—sucessão de Reinhardt como a nova Grande Marechal de Illumina, com a condição de participar do \"Programa Phospherus\". Com sua aspiração quase ao alcance, Wrath percebeu que suas ambições estavam passando por uma transformação silenciosa. No final, ela concordou com os termos do Comitê, mas um plano também se formou secretamente em seu coração.",
  str_mission_desc_4208015_long = "Além das fronteiras de Crepúsculo, também estão ocorrendo mudanças. Enquanto a Equipe de Reconhecimento Illumina rastreia o núcleo do \"Guardião Um\", eles se deparam com pistas inesperadas e cruciais. Enquanto isso, dentro do Tribunal Real de Lumopolis, Hydrad, atuando como enviado de Istvan, discute com Schwartz questões de reforço. Finalmente, Schwartz toma uma decisão - proteger os Aurorianos à maneira de Lumopolis.",
  str_mission_desc_4208020_long = "Sob a influência da lama, alguns soldados Illumina se transformam em Eclipsitas, lançando ataques contra seus próprios camaradas. Diante desse cenário terrível, Leo organiza a evacuação dos subordinados de Wrath enquanto lida pessoalmente com os soldados transformados. Em meio ao caos, o ferido Wrath retorna à luta, tentando trazer de volta aqueles enredados em um frenesi enlouquecido.",
  str_mission_desc_4208030_long = "Dado os recursos médicos limitados em Crepúsculo, você decide dividir-se em três equipes para a operação de resgate. Wrath continua a busca pelos soldados Illumina desaparecidos, enquanto Joselyne escolta soldados gravemente feridos para buscar refúgio no Forte Lumo. Quanto a você, Leo inicialmente sugere que pilote o Colossus e leve os refugiados para a segurança no Eraveil, mas você se mantém firme, insistindo em ficar para enfrentar a tempestade com todos.",
  str_mission_desc_4208040_long = "Charon parece ter antecipado a chegada de Victoria, mas fica surpreso ao saber que a estranha resistência encontrada não é obra de Victoria. Vice, ao saber da situação em Twilight, fica preocupado com sua segurança e, com a ajuda de Victoria, viaja para a cidade. No entanto, após uma breve estadia, a estranha força ataca o trem de Charon novamente.",
  str_mission_desc_4208041_long = "—",
  str_mission_desc_4208050_long = "A revelação da Bíblia Sangrenta deixa todos perplexos. Victoria rapidamente percebe que o \"Domínio\" do Wraith envolveu o trem. Para escapar do \"Domínio\", Charon enfrenta o Wraith diretamente, enquanto Victoria e três de seus subordinados realizam um ritual de sacrifício para se libertar do aperto. No momento em que Vice rompe o cerco, sua habilidade psíquica capta o ritmo do batimento cardíaco de Vice.",
  str_mission_desc_4208060_long = "Você pretende salvar este soldado com sua habilidade psíquica. No entanto, mesmo testemunhando as experiências pré-batalha do soldado, você ainda não consegue impedir sua descida à loucura. Nesse exato momento, os soldados começam a enlouquecer um após o outro. Enquanto Leo sugere que ele vá e acabe com eles, Wrath, assumindo seu papel como Grande Marechal, escolhe pessoalmente conceder um fim misericordioso àqueles camaradas atormentados além da conta.",
  str_mission_desc_4208070_long = "Ao abrir o portão da cidade, um feixe de luz sobrenatural faz com que todos se curvem em reverência. A devota Joselyne reconhece isso como a radiação divina trazida pela \"Santa\" do Templo de Lumopolis. A \"Santa\" cuida dos feridos, reconhece os esforços de Joselyne e decide acompanhá-la em sua jornada até Crepúsculo para ajudar aqueles que ainda precisam.",
  str_mission_desc_4208080_long = "Forsakin ri, dizendo que esses soldados caídos são sua \"obra de arte\" meticulosamente criada para todos verem. A raiva de Wrath arde, mas ela não age imprudentemente, cautelosa com a influência da \"Semente\" em seu corpo. Em seu caminho para recuperar os soldados que Forsakin tirou, Axelia testemunha o espetáculo horrível de soldados se voltando uns contra os outros. No momento mais crítico, uma equipe de reforço chega.",
  str_mission_desc_4208095_long = "Vivian reconhece Anatoli como a fonte do sinal e lembra como ele a obstruiu durante uma missão na Prisão Illumina. Acontece que Anatoli usou este mesmo método para testar a determinação de Vivian e, no final, decide ajudá-la a completar seu plano. Justamente quando os dois acreditam que o plano está progredindo bem, o sinal é interrompido abruptamente.",
  str_mission_desc_4208100_long = "A batalha em Crepúsculo solidifica a determinação de Leo em se posicionar como guardião da cidade. Joselyne, profundamente consciente dos conflitos entre as facções, expressa à \"Santa\" sua resolução de estabelecer um abrigo para os Aurorianos dentro da igreja. No entanto, a guerra está longe de acabar. Ao saber que várias forças convergiram para as defesas de Illumina, vocês decidem se reagrupar e avançar em direção à linha de defesa.",
  str_mission_desc_4208110_long = "No meio da intensa batalha dos soldados, Barton e Hiiro chegam como reforços. Após compartilhar a situação atual, Sharona permanece preocupado com a segurança de Wrath. No entanto, a aparição oportuna de Reinhardt aumenta a confiança de todos. Acontece que o plano de Wrath envolve não apenas defender o Crepúsculo, mas também resgatar Reinhardt e se reagrupar com eles na linha de frente.",
  str_mission_desc_4208111_long = "—",
  str_mission_desc_4208120_long = "Wrath pretende liderar suas tropas e cercar o exército Eclipsite, mas \"Engine VII\", sob a influência do Darkflow, se torna um obstáculo inesperado. Justo quando Axelia está em apuros lutando contra \"Engine VII\", Reinhardt vem em seu socorro. Com uma mistura de satisfação e alívio, Reinhardt observa Wrath retornar à linha de frente, mas Wrath se afasta voluntariamente, dando a Reinhardt o comando para liderar a batalha em curso.",
  str_mission_desc_4208130_long = "—",
  str_mission_desc_4208140_long = "Antes de partir, Forsakin, manipulando tanto os soldados Illumina quanto Engine VII, lança um ataque final e brutal contra o exército Illumina. Reinhardt percebe o envolvimento de Forsakin na operação do Eclipse e tenta argumentar com ela, instando-a a agir de acordo com sua própria vontade. No entanto, a resposta de Forsakin aumenta o abismo entre as antigas irmãs. Logo depois, soldados de Lumopolis e Crepúsculo se juntam à batalha na linha de defesa.",
  str_mission_desc_4208155_long = "A chuva cai sobre a linha de frente da Illumina. Quando para, a lama se dissipa, revelando a terra sob a luz do sol mais uma vez. Wrath olha para as pesadas baixas, culpando-se por sua falha como Grande Marechal. No entanto, Reinhardt elogia seu desempenho, afirmando que foi sua determinação inabalável que protegeu Twilight e seus soldados. No entanto, a verdadeira batalha ainda se aproxima.",
  str_mission_limit_4000001 = "Navegador, lute e conclua o estágio com <color=#e8d9bb>Vice</color>!",
  str_mission_limit_4000002 = "Lance seus membros do esquadrão e lute com <color=#e8d9bb>Vice</color>!",
  str_mission_limit_4000003 = "É melhor lançar outros membros para concluir o estágio com <color=#e8d9bb>Vice</color>. Experimente!",
  str_mission_leader_limit_4000002 = "Navegador, <color=#e8d9bb>Vice</color> é a melhor Capitã!",
  str_mission_desc_4209015 = "...",
  str_mission_desc_4209020 = "Um pesadelo vívido te acorda assustado vários dias depois, nas primeiras horas da manhã...",
  str_mission_desc_4209030 = "Na sua empolgação, você decola sem obter um horário ou local para o encontro, e as coisas certamente não parecem boas em Illumina agora...",
  str_mission_desc_4209040 = "Você fica chocado com a forma como Algol faz sua estreia, mas ainda mais surpreso com seu \"animal de estimação\" parasita.",
  str_mission_desc_4209050 = "Você e Vivian ficam maravilhados quando Algol os leva para o escritório dela. Existe realmente um lugar assim em Illumina?",
  str_mission_desc_4209065 = "...",
  str_mission_desc_4209070 = "Vários Eclipsitas aparecem repentinamente no Parque Tecnológico Illumina e bloqueiam seu caminho...",
  str_mission_desc_4209080 = "Os Eclipsitas continuam saindo do prédio, mas o que mais te choca é que Ulysses está seguindo silenciosamente atrás deles...",
  str_mission_desc_4209081 = "Parece que esses Soldados Illumina passam por uma transformação temível à noite. Tenha cuidado!",
  str_mission_desc_4209090 = "As palavras de Ulysses estão repletas de ameaças, e você viu perigo em suas visões...",
  str_mission_desc_4209100 = "Durante a quinta conferência de revisão, Ulysses relembra um capítulo de seu passado...",
  str_mission_desc_4209115 = "...",
  str_mission_desc_4209120 = "O que esse protótipo há muito selado tem a ver com Ulysses?",
  str_mission_desc_4209121 = "Esses Eclipsitas têm capacidades de contra-ataque muito aprimoradas, então tente não enfrentá-los em combate corpo a corpo.",
  str_mission_desc_4209130 = "Na sua empolgação ao ler as notas do Engenheiro, Ulysses se afastou cada vez mais de sua própria pesquisa...",
  str_mission_desc_4209140 = "Através do computador de Ulysses, você descobriu que ele acessou um armazém não registrado sem autorização...",
  str_mission_desc_4209150 = "Após derrotar os supersoldados, você volta sua atenção para o protótipo que ainda está em funcionamento...",
  str_mission_desc_4210015 = "...",
  str_mission_desc_4210020 = "Ulysses insiste que seus experimentos beneficiam a Illumina e se esforça para provar seu ponto de vista, mas isso desagrada profundamente Anatoli, que está bem perto...",
  str_mission_desc_4210030 = "Para acelerar a decodificação, você se conectou mentalmente com Bool para encontrar pistas.",
  str_mission_desc_4210045 = "...",
  str_mission_desc_4210050 = "Justo quando Algol acha que você coletou informações suficientes, um fator X aparece...",
  str_mission_desc_4210060 = "O que acontecerá quando você entrar no sistema do Guardião?",
  str_mission_desc_4210070 = "Quando uma crise estoura, algumas pessoas entram em pânico, e outras simplesmente não conseguem esperar...",
  str_mission_desc_4210071 = "O lugar onde os Soldados Illumina estão realizando sua missão secreta parece ser Lumópolis...",
  str_mission_desc_4210080 = "Ulysses chega ao Armazém Zero e abre ansiosamente o presente que ele tem preparado por anos...",
  str_mission_desc_4210090 = "Com esse som, você de repente percebe o significado daqueles sonhos vívidos, porém surreais...",
  str_mission_desc_4210100 = "Você sai correndo sem pensar, apenas para se encontrar tendo perdido a percepção disso...",
  str_mission_desc_4210110 = "A provocação do inimigo te irritou. Qual resposta você dará como um Celestita?",
  str_mission_desc_4210120 = "O Engenheiro mostrou sinais de recuo, mas o núcleo de defesa de Gannon ainda está desaparecido. O que fazer agora?",
  str_mission_desc_4210121 = "Os poderosos super soldados podem fortalecer todos os seus inimigos, então você deve impedi-los!",
  str_mission_desc_4210130 = "Depois que o núcleo é substituído, você ouve Ulysses falando em uma língua totalmente estrangeira...",
  str_mission_desc_4210140 = "Antes de sua visão desabar, ele se lembra de uma conversa em tempo de guerra no sanatório...",
  str_mission_desc_4210155 = "...",
  str_mission_desc_4209015_long = "Após um violento tremor, você e os soldados de Crepúsculo retornam a Eraveil após uma longa ausência. Os sobreviventes de Crepúsculo preparam um banquete farto; após se fartar de uma refeição perfeita, você inicia uma conversa com Soroz.",
  str_mission_desc_4209020_long = "Preocupado com a segurança de Vice, você passa dias sentado no terminal do seu Colossus, esperando ansiosamente por qualquer notícia de Reinhardt. De repente, você finalmente recebe a tão esperada mensagem.",
  str_mission_desc_4209030_long = "Como resultado de um problema com o sistema de defesa de Illumina, você é atacado por Eclipsitas no pátio de serviço de Illumina. Justamente então, a pessoa que o convidou para cá aparece de uma maneira mais inesperada.",
  str_mission_desc_4209040_long = "Algol apresenta seu companheiro Bool e explica suas razões para convidá-lo para Illumina. Ela sugere que os arquivos de dados de Soroz podem conter pistas sobre o Núcleo do Guardian One, que esperamos levar à descoberta do paradeiro de Vice.",
  str_mission_desc_4209050_long = "Ao beber uma xícara de café preparada pelo Guardião Um, Vivian parece finalmente relaxar um pouco. Após um breve descanso, todos voltam ao trabalho. Infelizmente, ninguém te contou sobre o método de comunicação único e bastante doloroso de Bool...",
  str_mission_desc_4209065_long = "Após uma análise demorada, você descobre um conjunto de coordenadas piscando escondido nos arquivos de dados de Soroz, que parecem ser anteriores a Eraveil por um bom tempo. Algol suspeita que o local de nascimento dos Colossi esteja nas profundezas da Zona Escura, então você se aproxima de um dos físicos especialistas da Illumina para perguntar sobre as coordenadas.",
  str_mission_desc_4209070_long = "Após derrotar os Eclipsitas, você descobre que seus corpos têm uma semelhança impressionante com os dos Aurorianos. Barton, que estava patrulhando o Parque Tecnológico Illumina, junta-se ao seu grupo e todos supõem que esses Eclipsitas eram provavelmente sujeitos de teste fugitivos do laboratório de Ulysses. Com a ajuda de Alglol, você segue para o laboratório e se prepara para questionar o pesquisador.",
  str_mission_desc_4209080_long = "Ulysses não nega que os Eclipsitas de antes haviam escapado de seu laboratório, e ele te convida para ir mais fundo no prédio para o que ele chama de \"pequeno experimento\". Curioso sobre várias coisas que ele mencionou, você aceita seu convite.",
  str_mission_desc_4209090_long = "Após presenciar uma cena perigosa e horrível, Ulysses é levado pelas autoridades da Federação Illumina. Embora você ainda não tenha certeza do porquê ele mostrou essas coisas, parece que o sol está começando a brilhar novamente na cidade de Gannon. Você e seus amigos esperam que essa crise termine em breve.",
  str_mission_desc_4209100_long = "Anos atrás, um jovem Ulysses dedicou-se a melhorar a sobrevivência dos Aurorianos. Enquanto pesquisava a tecnologia de engenharia genética da Illumina, que havia sido passada de séculos atrás, ele descobre um nome há muito esquecido pela história. Ver este nome enche-o de esperança para o futuro de todos os Aurorianos.",
  str_mission_desc_4209115_long = "Joyce conta a você sobre uma pedra flutuante, que apareceu nas coordenadas dentro da Dark Zone, e as informações correspondem às imagens que você viu na mente de Ulysses. Só então Algol percebe que Ulysses tem escondido seu trabalho no protótipo do Guardião o tempo todo.",
  str_mission_desc_4209120_long = "Na audiência, todos ficam chocados ao descobrir que Ulysses tem pesquisado secretamente sobre a máquina antiga. À medida que essas revelações se desdobram, você e Algol continuam procurando o protótipo na cidade de Gannon. No entanto, tão perigosos quanto essa máquina, são os super-soldados que emitem Darkflow escondidos nas sombras.",
  str_mission_desc_4209130_long = "Ulysses propõe um experimento audacioso, o que faz com que Robby, seu colega de longa data, suspeite dele. Quem é \"o Engenheiro\" e como ele convenceu Ulysses a tomar medidas tão radicais com sua pesquisa?",
  str_mission_desc_4209140_long = "Quando Algol chega ao Armazém Zero, ela fica animada ao descobrir que o protótipo do Guardião ainda está operacional. Infelizmente, sua intrusão também desencadeia um ataque pelos super-soldados armazenados no prédio.",
  str_mission_desc_4209150_long = "Quando Algol viu o protótipo pela primeira vez, ela ainda era estudante de Ulysses. Mais surpreendente, no entanto, é o fato de que Ulysses manteve-o operacional em seu armazém privado mesmo depois de ter sido selado por razões de segurança. Enquanto você e seus amigos tentam acessar o misterioso protótipo, vocês são preenchidos com uma mistura de antecipação e medo.",
  str_mission_desc_4210015_long = "Você fica impressionado com as funções impressionantes de Bool e sua velocidade de processamento. Conforme Algol relata a história de como se conheceram pela primeira vez, você lentamente percebe o significado por trás das etiquetas em seu corpo.",
  str_mission_desc_4210020_long = "Vem à luz que o verdadeiro propósito da Undercity 80 era selecionar candidatos para o projeto do Sol Artificial. Enquanto coletava informações cruciais sobre o projeto, a equipe de reconhecimento de Anatoli é finalmente eliminada. Inconformado com a perda de sua equipe, Anatoli exige que o Comitê tente e puna Ulysses por seus crimes.",
  str_mission_desc_4210030_long = "Após usar seus poderes psíquicos em Bool, você é sobrecarregado por uma enxurrada infinita de números e sequências. Para extrair as informações que você precisa, Algol compartilha com você sua técnica para lidar com cargas de trabalho difíceis. Você tenta novamente e, aparentemente, consegue obter alguns dados úteis.",
  str_mission_desc_4210045_long = "Assim como Yingel e Axelia, Sean também é um produto do Programa Phospherus. No entanto, Sean foi considerado um fracasso no início do programa e enviado para o Crepúsculo. Depois de aprender sobre suas origens, Sean começa a se perguntar se seu propósito na vida é se tornar uma arma de guerra impiedosa.",
  str_mission_desc_4210050_long = "A ligação com a mente de Bool causa uma quantidade considerável de tontura e desconforto. Algol lhe dá um limite de dois minutos, durante o qual você deve recuperar o máximo de informações possível. Felizmente, você sai relativamente ileso, mas algo parece estar incomodando Algol. O que no mundo poderia ter derrubado uma civilização avançada o suficiente para criar essa tecnologia?",
  str_mission_desc_4210060_long = "Você é pego de surpresa pela situação na Cidade Gannon. Algol continua desesperadamente procurando uma maneira de entrar no sistema, apenas para descobrir que os tremores violentos estão sendo causados por um inimigo invisível. O julgamento de Ulysses também é temporariamente suspenso. Justo quando você pensa que a crise está quase acabando, o inimigo invisível aparece na tela do protótipo...",
  str_mission_desc_4210070_long = "Ulysses afirma já ter elaborado uma maneira de derrotar o inimigo, e Belisaria concorda com sua operação, altera os preparativos anteriores e lança urgentemente o plano pré-fabricado.",
  str_mission_desc_4210080_long = "Os super-soldados armazenados no armazém são o resultado de anos de pesquisa científica de Ulysses, bem como seu presente para o Engenheiro. No entanto, para surpresa de Ulysses, o Engenheiro logo assume o controle deles e os usa para atacar todos os compatriotas de Illumina.",
  str_mission_desc_4210090_long = "\"Vá para casa, Celestita.\" Uma mensagem enigmática para muitos, mas que você já ouviu em seus sonhos inúmeras vezes. Quem é ele? Para onde exatamente ele quer que você vá? Enquanto você luta no limite de sua inteligência, de repente recebe a notícia de que Soroz foi ativado.",
  str_mission_desc_4210100_long = "O momento da despedida finalmente chegou, mas você não sente nada. Por razões desconhecidas, você já imaginou esse cenário mais vezes do que pode contar. O perigo segue de perto na esteira de sua tristeza, mas um pequeno amigo intervém e bloqueia um golpe fatal destinado a você.",
  str_mission_desc_4210110_long = "Dentro da consciência de Figerald, você parece testemunhar o processo pelo qual o Engenheiro escraviza os outros. Não só isso, você vê memórias distantes de um abismo profundo e restos esqueléticos de Colossus emergindo da mente de Figerald...",
  str_mission_desc_4210120_long = "Para proteger a cidade de Gannon, o companheiro de Algol, Guardian One, oferece resolutamente seu próprio Núcleo. Enquanto isso, para obter poder de computação suficiente para a transição, Reinhardt aciona um protocolo de emergência para redirecionar o poder de processamento de todos os computadores em Gannon City para sua localização.",
  str_mission_desc_4210130_long = "Algol descobre que a linguagem de computador usada pelo Sistema Guardião está de alguma forma relacionada à linguagem usada pelos Eclipsitas. Ulysses se gaba de que pode mudar o mundo inteiro, mas você não tem desejo de viver em um mundo modificado por suas mãos.",
  str_mission_desc_4210140_long = "Qual é mais trágico, a perda da fé ou a incapacidade de realizar os sonhos? Ulysses faz a você uma última pergunta antes de cair aos seus pés. Sem mais poder responder, esta pode ser a última vez que ele pondera essa questão.",
  str_mission_desc_4210155_long = "Após ficar inconsciente por três dias, você acorda e descobre que a crise na Cidade Gannon já passou. No entanto, o que te espera agora é uma missão de exploração ainda mais perigosa. Você se lembra de como foi salvo ao usar seus poderes e se pergunta se alguém naquele espaço brilhante, semelhante a um lago, pode oferecer a orientação que você procura.",
  str_mission_desc_4301015 = "...",
  str_mission_desc_4301020 = "Dentro de um vasto centro de comando temporário, o Comitê da Expedição Conjunta Astra convoca uma conferência crucial sobre o futuro dos Aurorianos.",
  str_mission_desc_4301030 = "Devido ao encontro com correntes de ar extremas, sua aeronave cai inesperadamente nas planícies nevadas na borda de Northland...",
  str_mission_desc_4301040 = "Você segue a trilha de sangue, mas ela misteriosamente desaparece ao longo do caminho...",
  str_mission_desc_4301055 = "Enquanto Bethlehem te acompanha para fora da caverna, ela sente o campo de energia único dentro dela e elabora uma solução para superar o aperto.",
  str_mission_desc_4301060 = "Diante da atual crise em Northland, Bethlehem busca conselho com o Ancião da Neve Fox sobre despertar o Refúgio Primordial para limpar a poluição que assola as planícies de neve.",
  str_mission_desc_4301070 = "...",
  str_mission_desc_4301080 = "Com a neve pesada cobrindo a fronteira, você chega à tribo que nutriu Tiare, começando a procurar pelo terceiro pinheiro.",
  str_mission_desc_4301090 = "Com o despertar do Refúgio Primordial, um novo farol é erguido. Tiare brande sua poderosa lança, avançando mais uma vez em direção àquele poderoso Eclipsita.",
  str_mission_desc_4301105 = "...",
  str_mission_desc_4301015_long = "Bethlehem relembra um encontro passado. Anos atrás, enquanto patrulhava a Floresta Snowpine na borda de Northland, ela teve um breve encontro com o Snow Fox que vivia lá. Tiare, a criança criada por aquele Snow Fox, agora serve como guarda de Bethlehem, vivendo no Palácio de Inverno, mas ainda se preocupa com sua tribo.",
  str_mission_desc_4301020_long = "Delegados de Lumópolis, Umbraton e da União dos Correios trocaram opiniões sobre os preparativos para a exploração da Federação Illumina. Após a reunião, Reinhardt designa você e Carleen para investigar o status de estabelecimento do posto avançado de Northland.",
  str_mission_desc_4301030_long = "Ao tropeçar acidentalmente no território da tribo da fronteira, você fica perplexo com as manchas de sangue espalhadas pelo chão. As reações subsequentes de Tiare e das Raposas da Neve sugerem que as coisas não são tão simples quanto parecem. Apesar de sua oposição veemente, você ainda decide segui-los para ver o que exatamente aconteceu.",
  str_mission_desc_4301040_long = "Superando seus medos internos, você usa suas habilidades psíquicas para rastrear Tiare e as raposas da neve. Eventualmente, você se depara com as manchas de sangue que eles deixaram e inesperadamente descobre que dois de seus amigos do Rediesel Wrench também vieram para a Northland com sua aeronave. Mas o que você não sabia, é que um poderoso Eclipsite está à espreita nas proximidades.",
  str_mission_desc_4301055_long = "Liderado pelo Ancião da Neve Fox, você chega ao antigo altar guardado pela tribo da Neve Fox por gerações. Aqui, sua força ressoa com o poder antigo, e a lenda dos \"Três Pinheiros\" se desdobra. Para surpresa do Ancião da Neve Fox, não foi a família real que tomou os pinheiros, mas sim os pinheiros que escolheram a família real e reconheceram a rainha.",
  str_mission_desc_4301060_long = "Enquanto Bethlehem enfrenta o Eclipsita sozinho, você decide procurar por outras duas árvores de pinho junto com Tiare. Novio sugere que, como o poder antigo diminuiu, para encontrar os pinheiros, você deve buscar pistas na lenda das \"Três Árvores de Pinho\".",
  str_mission_desc_4301070_long = "Carregando você em seus ombros, Tiare corre todo o caminho, chegando finalmente ao Tribunal de Northland. Quando você está perdido, as palavras de Zarya oferecem uma pista. Acontece que o pinheiro cortado há muito tempo foi transformado no trono da rainha, mas como a rainha nunca se senta nele, o trono tem acumulado poeira no tribunal.",
  str_mission_desc_4301080_long = "Mergulhando nas memórias de Tiare, você descobre o desacordo entre o Ancião da Neve Fox e a avó de Tiare a respeito do futuro dela. A questão chave de sua disputa é algo sobre uma laje de pedra simbolizando um compromisso antigo, que é exatamente o que você está procurando. Com a ajuda de Tiny One e Roy, você consegue localizar o terceiro pinheiro e trazê-lo de volta ao altar.",
  str_mission_desc_4301090_long = "O ataque de Tiare desperta memórias no Eclipsita, lembrando-o de seu passado e das razões por trás de seu treinamento incansável. Ao tentar um golpe final contra você, você o expulsa de Northland. Sob a luz do Farol, você dá um passo histórico à frente, aventurando-se na Dark Zone.",
  str_mission_desc_4301105_long = "Apesar dos Eclipsitas permanecerem invictos e o posto avançado de Northland ainda estar em construção, você decide fazer preparativos ativos e prosseguir com sua exploração na Zona Sombria no tempo que virá. Antes de partir, você recebe o Minério Lumina entregue por Tiare. Parado por perto, Bethlehem encontra consolo e contentamento, sabendo que o guarda de Northland, Tiare, cresceu e amadureceu.",
  str_mission_desc_4220020 = "Você encontra Pepita, mas ela realiza um grande ato de fuga. Ela tem sido procurada por várias facções, mas por quê?",
  str_mission_desc_4220030 = "O amigo de Pepita é um fantasma, e eles parecem um par de lunáticos...",
  str_mission_desc_4220040 = "Pepita e Ursura se encontram, ambos assombrados por seus passados.",
  str_mission_desc_4220050 = "Para proteger Pepita, que opera na Zona Escura, Reinhardt faz um pacto com Schwartz. Mas a Divisão de Investigação de Heréticos realmente aceitará isso?",
  str_mission_desc_4220060 = "A região conhecida como \"Coral Grounds\" é estranhamente bela, mas exala um cheiro de morte.",
  str_mission_desc_4220061 = "Esses Eclipsitas parecem familiares, mas há algo profundamente estranho neles.",
  str_mission_desc_4220070 = "Uma raça misteriosa prosperou aqui até os Fantasmas...",
  str_mission_desc_4220071 = "A noite eterna é o lar deles, e eles estão presos em seu ciclo interminável.",
  str_mission_desc_4220090 = "Diante da restrição de Ursura, Pepita se queima para declarar sua resistência—Não!",
  str_mission_desc_4220100 = "A Divisão de Investigação de Hereges finalmente enfrenta o maior \"herege\" como eles desejavam. Mas a confiança de Victoria em aparecer sozinho diz muito.",
  str_mission_desc_4220110 = "À medida que a noite eterna se aproxima, Victoria desencadeia seu poder arcano - quando o \"sol\" nascer, como Ursura irá revidar?",
  str_mission_desc_4220015_long = "Enquanto sua aeronave voa pela noite, rastreando a equipe de expedição e Vice, uma misteriosa bola de luz chamou sua atenção. Enquanto isso, Reinhardt e o Comitê estão tomando medidas. Uma nova \"sombra\" está agora em destaque.",
  str_mission_desc_4220020_long = "Você encontra a equipe de Pepita na Zona Escura, mas ela foge no momento em que te vê. A inteligência de Philyshy revela que Pepita é procurada tanto por Illumina quanto por Lumopolis. Logo depois, a equipe de Lumopolis aparece. Eles já lidaram com ela antes, mas o Comitê interveio antes que eles pudessem prendê-la na última vez.",
  str_mission_desc_4220030_long = "Pepita aparece e engana a todos. Ela não só é imune à Zona Sombria, mas agora está do lado do Espectro e tem um familiar poderoso deles. Depois de causar confusão, ela sai casualmente de braços dados com o Espectro.",
  str_mission_desc_4220040_long = "Pepita lembra de sua infância, quando seu pai a traiu e viveu uma vida controlada pelo Comitê. Eles substituíram seu frágil coração por um forte artificial, deixando-a sem escolha a não ser seguir suas ordens. Apesar de tudo, ela ainda não quer machucar os outros.",
  str_mission_desc_4220050_long = "A condição de Pepita é hereditária, mas depois que seu pai a entregou ao Comitê, ela parou de confiar na Illumina e acabou se rebelando e se juntando à Verdadeira Ordem. Enquanto Reinhardt e Schwartz querem colocá-la de volta no caminho certo, o Capitão da Divisão de Investigação de Heréticos não tem tanta certeza disso.",
  str_mission_desc_4220060_long = "Guiado pelo tesouro do Capitão da Divisão de Investigação de Heréticos, vocês se encontram em uma área desconhecida. Parece que os Aurorianos já viveram aqui, mas eles se foram há muito tempo.",
  str_mission_desc_4220070_long = "Você toca o cadáver e vislumbra o passado da Tribo da Tundra. Essas pessoas foram presas pelo coral de Ursura, passando suas vidas inteiras trabalhando para um certo forno sem liberdade. De vez em quando, Yodu, um fantasma, verificava o progresso deles. Mas um dia, Yodu decidiu que eles não valiam mais a pena e matou todos.",
  str_mission_desc_4220085_long = "Pepita, presa com um coração controlado pelo Comitê, olha com inveja para o coração de coral de Ursura. Ursura faz uma oferta: se Pepita concordar em ser dela para sempre, ela fará um coração de coral para ela. Lembrando de seu primeiro encontro, Pepita decide que nunca se submeterá a ninguém.",
  str_mission_desc_4220090_long = "Pepita adere ao seu princípio de \"ser livre ou estar morto\" e corta laços com Ursura.\nVocê encontra uma barreira que bloqueia Darkflow, mas de repente, Victoria aparece, reivindicando-a como sua. À medida que as coisas começam a esquentar, Ursura aparece perseguindo Pepita—mas curiosamente, ela se assusta no segundo em que vê Victoria.",
  str_mission_desc_4220100_long = "A equipe de expedição não conseguia concordar se deveriam atacar Victoria, fazendo o grupo se desintegrar. O Capitão da Inquisição de Heréticos ataca Victoria sozinho e é derrotado. Victoria então revela uma verdade - agora você finalmente percebe que a luz que te guiava o tempo todo era Vice, que havia caído nas profundezas do Rio Prístino.",
  str_mission_desc_4220110_long = "Victoria vai atrás de Ursura sozinho e a enfrenta em uma luta. Sob a técnica secreta de Victoria, Ursura é facilmente derrotada.\nEnquanto isso, Charon encontra um \"parente morto\" chamado Wilhelm. Para salvar Vice, Charon engole seu orgulho e começa a aprender a técnica secreta do vampiro com ele.",
  str_mission_desc_4220125_long = "Pepita corre de volta para a base, mas é caçado pelo Capitão da Divisão de Investigação de Heréticos e pelo Carrasco do Comitê...\nNo fundo da noite eterna, Figerald é de alguma forma remontado pelos Membros do Eclipse, apenas para ser usado como degraus para Forsakin se tornar um fantasma.\nCom a ressurreição de Ursura, os novos Membros do Eclipse se reúnem, discutindo a técnica secreta de Victoria...Após cair do penhasco, Pepita é salva por seu familiar, fazendo-a perceber que Ursura ainda está viva. O trem de Charon também rompe o espaço e a localiza...",
  str_mission_error_failed = "Erro de servidor",
  str_mission_error_invalid_level = "Est. inválido",
  str_mission_error_invalid_power = "Prismas insuficientes. Incapaz de desafiar!",
  str_mission_error_not_exist = "Estágio não encontrado",
  str_mission_error_is_lock = "Est. trancado",
  str_mission_error_story_already_active = "História disp.",
  str_mission_error_invalid_id = "Est. inválido",
  str_mission_error_story_invalid_type = "Tipo de est. inválido",
  str_mission_error_invalid_chapter_award = "Pedido de recomp. de cap. inválido",
  str_mission_error_invalid_chapter_award_star = "Estrelas inválidas",
  str_mission_error_invalid_chapter_award_receive = "Recompensa retirada",
  str_mission_error_invalid_chapter_award_config = "Recomp. retirada não corresponde à configuração",
  str_mission_error_dirty_name = "Contém palavras inadequadas. Tente de novo!",
  str_mission_error_power_not_enough = "{1} insuficiente(s). Incapaz de desafiar!"
}
return config
